begin;
    with j as (select * from jsonb_to_recordset($law7v011$[{"code_id":"GK_RF","article_number":"52","version_date":"1994-11-30","article_text":"Хозяйственное товарищество действует на основании учредительного договора, который заключается его учредителями (участниками) и к которому применяются правила настоящего Кодекса об уставе юридического лица.\n\nГосударственная корпорация действует на основании федерального закона о такой государственной корпорации. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 236-ФЗ)\n\nТиповой устав, утвержденный уполномоченным государственным органом, не содержит сведений о наименовании, фирменном наименовании, месте нахождения и размере уставного капитала юридического лица. Такие сведения указываются в едином государственном реестре юридических лиц.\n\n(Пункт в редакции Федерального закона от 29.06.2015 № 209-ФЗ)\n\nВо внутреннем регламенте и в иных внутренних документах юридического лица могут содержаться положения, не противоречащие учредительному документу юридического лица.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 52. Учредительные документы юридических лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a53c135f4a1e47cbc1b6a61cc1014dcacc4c43571b07cc198e682a9a8349c05"},{"code_id":"GK_RF","article_number":"53","version_date":"1994-11-30","article_text":"Порядок образования и компетенция органов юридического лица определяются настоящим Кодексом, другим законом и учредительным документом, если иное не предусмотрено настоящим Кодексом или другим законом. (В редакции Федерального закона от 25.02.2022 № 20-ФЗ)\n\nУчредительным документом может быть предусмотрено, что полномочия выступать от имени юридического лица предоставлены нескольким лицам, действующим совместно или независимо друг от друга. Сведения об этом подлежат включению в единый государственный реестр юридических лиц.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 53. Органы юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdccf7b609b149cab08a599e622528e93ad67de5a4135e2299a77e9b84c1f520"},{"code_id":"GK_RF","article_number":"53.1","version_date":"1994-11-30","article_text":"1. Лицо, которое в силу закона, иного правового акта или учредительного документа юридического лица уполномочено выступать от его имени (пункт 3 статьи 53), обязано возместить по требованию юридического лица, его учредителей (участников), выступающих в интересах юридического лица, убытки, причиненные по его вине юридическому лицу.\n\nЛицо, которое в силу закона, иного правового акта или учредительного документа юридического лица уполномочено выступать от его имени, несет ответственность, если будет доказано, что при осуществлении своих прав и исполнении своих обязанностей оно действовало недобросовестно или неразумно, в том числе если его действия (бездействие) не соответствовали обычным условиям гражданского оборота или обычному предпринимательскому риску.\n\n2. Ответственность, предусмотренную пунктом 1 настоящей статьи, несут также члены коллегиальных органов юридического лица, за исключением тех из них, кто голосовал против решения, которое повлекло причинение юридическому лицу убытков, или, действуя добросовестно, не принимал участия в голосовании.\n\n3. Лицо, имеющее фактическую возможность определять действия юридического лица, в том числе возможность давать указания лицам, названным в пунктах 1 и 2 настоящей статьи, обязано действовать в интересах юридического лица разумно и добросовестно и несет ответственность за убытки, причиненные по его вине юридическому лицу.\n\n4. В случае совместного причинения убытков юридическому лицу лица, указанные в пунктах 1 - 3 настоящей статьи, обязаны возместить убытки солидарно.\n\n5. Соглашение об устранении или ограничении ответственности лиц, указанных в пунктах 1 и 2 настоящей статьи, за совершение недобросовестных действий, а в публичном обществе за совершение недобросовестных и неразумных действий (пункт 3 статьи 53) ничтожно.\n\nСоглашение об устранении или ограничении ответственности лица, указанного в пункте 3 настоящей статьи, ничтожно.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 53.1. Ответственность лица, уполномоченного выступать от имени юридического лица, членов коллегиальных органов юридического лица и лиц, определяющих действия юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5af03af497a7f8d539f24973b49eadabef71d83140efeffdf4f9c9c7a50ac22b"},{"code_id":"GK_RF","article_number":"53.2","version_date":"1994-11-30","article_text":"В случаях, если настоящий Кодекс или другой закон ставит наступление правовых последствий в зависимость от наличия между лицами отношений связанности (аффилированности), наличие или отсутствие таких отношений определяется в соответствии с законом.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 53.2. Аффилированность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"789cd55b607c4df68ddc04635eaf8843acd3f952b3d4e2fd615e38eb116dc5f6"},{"code_id":"GK_RF","article_number":"54","version_date":"1994-11-30","article_text":"Включение в наименование юридического лица официального наименования Российская Федерация или Россия, а также слов, производных от этого наименования, допускается в случаях, предусмотренных законом, указами Президента Российской Федерации или актами Правительства Российской Федерации, либо по разрешению, выданному в порядке, установленном Правительством Российской Федерации.\n\nПолные или сокращенные наименования федеральных органов государственной власти не могут использоваться в наименованиях юридических лиц, за исключением случаев, предусмотренных законом, указами Президента Российской Федерации или актами Правительства Российской Федерации.\n\nНормативными правовыми актами субъектов Российской Федерации может быть установлен порядок использования в наименованиях юридических лиц официального наименования субъектов Российской Федерации.\n\nЮридическое лицо несет риск последствий неполучения юридически значимых сообщений (статья 1651), доставленных по адресу, указанному в едином государственном реестре юридических лиц, а также риск отсутствия по указанному адресу своего органа или представителя. Сообщения, доставленные по адресу, указанному в едином государственном реестре юридических лиц, считаются полученными юридическим лицом, даже если оно не находится по указанному адресу.\n\nПри наличии у иностранного юридического лица представителя на территории Российской Федерации сообщения, доставленные по адресу такого представителя, считаются полученными иностранным юридическим лицом.\n\nТребования к фирменному наименованию устанавливаются настоящим Кодексом и другими законами. Права на фирменное наименование определяются в соответствии с правилами раздела VII настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 54. Наименование, место нахождения и адрес юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8826419fb662f50ebc1a822d8c821a3a5d42b8ec22da8ee6e1d3ed81c213d869"},{"code_id":"GK_RF","article_number":"55","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n1. Представительством является обособленное подразделение юридического лица, расположенное вне места его нахождения, которое представляет интересы юридического лица и осуществляет их защиту.\n\n2. Филиалом является обособленное подразделение юридического лица, расположенное вне места его нахождения и осуществляющее все его функции или их часть, в том числе функции представительства.\n\n3. Представительства и филиалы не являются юридическими лицами. Они наделяются имуществом создавшим их юридическим лицом и действуют на основании утвержденных им положений.\n\nРуководители представительств и филиалов назначаются юридическим лицом и действуют на основании его доверенности.\n\nПредставительства и филиалы должны быть указаны в едином государственном реестре юридических лиц. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 55. Представительства и филиалы юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e4778e42f66052ef0db4e54710b17f4c4004ab2d28386f128be9a9bbec636e3d"},{"code_id":"GK_RF","article_number":"56","version_date":"1994-11-30","article_text":"1. Юридическое лицо отвечает по своим обязательствам всем принадлежащим ему имуществом.\n\nОсобенности ответственности казенного предприятия и учреждения по своим обязательствам определяются правилами абзаца третьего пункта 6 статьи 113, пункта 3 статьи 12321, пунктов 3 - 6 статьи 12322 и пункта 2 статьи 12323 настоящего Кодекса. Особенности ответственности религиозной организации определяются правилами пункта 2 статьи 12328 настоящего Кодекса.\n\n2. Учредитель (участник) юридического лица или собственник его имущества не отвечает по обязательствам юридического лица, а юридическое лицо не отвечает по обязательствам учредителя (участника) или собственника, за исключением случаев, предусмотренных настоящим Кодексом или другим законом.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 56. Ответственность юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2537a9f46e6a89a59d562e246ca27565983acc184231744f6dd282ee6d40b1d"},{"code_id":"GK_RF","article_number":"57","version_date":"1994-11-30","article_text":"1. Реорганизация юридического лица (слияние, присоединение, разделение, выделение, преобразование) может быть осуществлена по решению его учредителей (участников) или органа юридического лица, уполномоченного на то учредительным документом.\n\nДопускается реорганизация юридического лица с одновременным сочетанием различных ее форм, предусмотренных абзацем первым настоящего пункта.\n\nДопускается реорганизация с участием двух и более юридических лиц, в том числе созданных в разных организационно-правовых формах, если настоящим Кодексом или другим законом предусмотрена возможность преобразования юридического лица одной из таких организационно-правовых форм в юридическое лицо другой из таких организационно-правовых форм.\n\nОграничения реорганизации юридических лиц могут быть установлены законом.\n\nОсобенности реорганизации кредитных, страховых, клиринговых организаций, специализированных финансовых обществ, специализированных обществ проектного финансирования, профессиональных участников рынка ценных бумаг, акционерных инвестиционных фондов, управляющих компаний инвестиционных фондов, паевых инвестиционных фондов и негосударственных пенсионных фондов, негосударственных пенсионных фондов и иных некредитных финансовых организаций, акционерных обществ работников (народных предприятий) определяются законами, регулирующими деятельность таких организаций.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n2. В случаях, установленных законом, реорганизация юридического лица в форме его разделения или выделения из его состава одного или нескольких юридических лиц осуществляется по решению уполномоченных государственных органов или по решению суда.\n\nЕсли учредители (участники) юридического лица, уполномоченный ими орган или орган юридического лица, уполномоченный на реорганизацию его учредительным документом, не осуществят реорганизацию юридического лица в срок, определенный в решении уполномоченного государственного органа, суд по иску указанного государственного органа назначает в установленном законом порядке арбитражного управляющего юридическим лицом и поручает ему осуществить реорганизацию юридического лица. С момента назначения арбитражного управляющего к нему переходят полномочия по управлению делами юридического лица. Арбитражный управляющий выступает от имени юридического лица в суде, составляет передаточный акт и передает его на рассмотрение суда вместе с учредительными документами юридических лиц, создаваемых в результате реорганизации. Решение суда об утверждении указанных документов является основанием для государственной регистрации вновь создаваемых юридических лиц. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n3. В случаях, установленных законом, реорганизация юридических лиц в форме слияния, присоединения или преобразования может быть осуществлена лишь с согласия уполномоченных государственных органов.\n\nПри реорганизации юридического лица в форме присоединения к нему другого юридического лица первое из них считается реорганизованным с момента внесения в единый государственный реестр юридических лиц записи о прекращении деятельности присоединенного юридического лица.\n\nГосударственная регистрация юридического лица, создаваемого в результате реорганизации (в случае регистрации нескольких юридических лиц - первого по времени государственной регистрации), допускается не ранее истечения соот\n\nветствующего срока для обжалования решения о реорганизации (пункт 1 статьи 601). (Дополнение абзацем - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 57. Реорганизация юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb62e3552540543d9beba57248c1046441e742eee53f966ee7109bb0932783b2"},{"code_id":"GK_RF","article_number":"58","version_date":"1994-11-30","article_text":"К отношениям, возникающим при реорганизации юридического лица в форме преобразования, правила статьи 60 настоящего Кодекса не применяются.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 58. Правопреемство при реорганизации юридических лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a62965afc36ddf546c1f64968187f46f8d37318f95cb577a40a33022892e8cb6"},{"code_id":"GK_RF","article_number":"59","version_date":"1994-11-30","article_text":"1. Передаточный акт должен содержать положения о правопреемстве по всем обязательствам реорганизованного юридического лица в отношении всех его кредиторов и должников, включая обязательства, оспариваемые сторонами, а также порядок определения правопреемства в связи с изменением вида, состава, стоимости имущества, возникновением, изменением, прекращением прав и обязанностей реорганизуемого юридического лица, которые могут произойти после даты, на которую составлен передаточный акт.\n\n2. Передаточный акт утверждается учредителями (участниками) юридического лица или органом, принявшим решение о реорганизации юридического лица, и представляется вместе с учредительными документами для государственной регистрации юридических лиц, создаваемых в результате реорганизации, или внесения изменений в учредительные документы существующих юридических лиц.\n\nНепредставление вместе с учредительными документами передаточного акта, отсутствие в нем положений о правопреемстве по всем обязательствам реорганизованного юридического лица влекут отказ в государственной регистрации юридических лиц, создаваемых в результате реорганизации.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 59. Передаточный акт","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"44635f9abadb692d2594b228d7414c20a8de0a6dfa46ec24900b2dcbc8989a55"},{"code_id":"GK_RF","article_number":"60","version_date":"1994-11-30","article_text":"1. В течение трех рабочих дней после даты принятия решения о реорганизации юридического лица оно обязано уведомить в письменной форме уполномоченный государственный орган, осуществляющий государственную регистрацию юридических лиц, о начале процедуры реорганизации с указанием формы реорганизации. В случае участия в реорганизации двух и более юридических лиц такое уведомление направляется юридическим лицом, последним принявшим решение о реорганизации или определенным решением о реорганизации. На основании такого уведомления уполномоченный государственный орган, осуществляющий государственную регистрацию юридических лиц, вносит в единый государственный реестр юридических лиц запись о том, что юридические лица находятся в процессе реорганизации.\n\nРеорганизуемое юридическое лицо после внесения в единый государственный реестр юридических лиц записи о начале процедуры реорганизации дважды с периодичностью один раз в месяц опубликовывает в средствах массовой информации, в которых опубликовываются данные о государственной регистрации юридических лиц, уведомление о своей реорганизации. В случае участия в реорганизации двух и более юридических лиц уведомление о реорганизации опубликовывается от имени всех участвующих в реорганизации юридических лиц юридическим лицом, последним принявшим решение о реорганизации или определенным решением о реорганизации. В уведомлении о реорганизации указываются сведения о каждом участвующем в реорганизации, создаваемом или продолжающем деятельность в результате реорганизации юридическом лице, форма реорганизации, описание порядка и условий заявления кредиторами своих требований, иные сведения, предусмотренные законом.\n\nЗаконом может быть предусмотрена обязанность реорганизуемого юридического лица уведомить в письменной форме кредиторов о своей реорганизации.\n\n2. Кредитор юридического лица, если его права требования возникли до опубликования первого уведомления о реорганизации юридического лица, вправе потребовать в судебном порядке досрочного исполнения соответствующего обязательства должником, а при невозможности досрочного исполнения - прекращения обязательства и возмещения связанных с этим убытков, за исключением случаев, установленных законом или соглашением кредитора с реорганизуемым юридическим лицом.\n\nТребования о досрочном исполнении обязательства или прекращении обязательства и возмещении убытков могут быть предъявлены кредиторами не позднее чем в течение тридцати дней после даты опубликования последнего уведомления о реорганизации юридического лица.\n\nПраво, предусмотренное абзацем первым настоящего пункта, не предоставляется кредитору, уже имеющему достаточное обеспечение.\n\nПредъявленные в указанный срок требования должны быть исполнены до завершения процедуры реорганизации, в том числе внесением долга в депозит в случаях, предусмотренных статьей 327 настоящего Кодекса.\n\nКредитор не вправе требовать досрочного исполнения обязательства или прекращения обязательства и возмещения убытков, если в течение тридцати дней с даты предъявления кредитором этих требований ему будет предоставлено обеспечение, признаваемое достаточным в соответствии с пунктом 4 настоящей статьи.\n\nПредъявление кредиторами требований на основании настоящего пункта не является основанием для приостановления процедуры реорганизации юридического лица.\n\n3. Если кредитору, потребовавшему в соответствии с правилами настоящей статьи досрочного исполнения обязательства или прекращения обязательства и возмещения убытков, такое исполнение не предоставлено, убытки не возмещены и не предложено достаточное обеспечение исполнения обязательства, солидарную ответственность перед кредитором наряду с юридическими лицами, созданными в результате реорганизации, несут лица, имеющие фактическую возможность определять действия реорганизованных юридических лиц (пункт 3 статьи 531), члены их коллегиальных органов и лицо, уполномоченное выступать от имени реорганизованного юридического лица (пункт 3 статьи 53), если они своими действиями (бездействием) способствовали наступлению указанных последствий для кредитора, а при реорганизации в форме выделения солидарную ответственность перед кредитором наряду с указанными лицами несет также реорганизованное юридическое лицо.\n\n4. Предложенное кредитору обеспечение исполнения обязательств реорганизуемого юридического лица или возмещения связанных с его прекращением убытков считается достаточным, если:\n\n1) кредитор согласился принять такое обеспечение;\n\n2) кредитору выдана независимая безотзывная гарантия кредитной организацией, кредитоспособность которой не вызывает обоснованных сомнений, со сроком действия, не менее чем на три месяца превышающим срок исполнения обеспечиваемого обязательства, и с условием платежа по предъявлении кредитором требований к гаранту с приложением доказательств неисполнения обязательства реорганизуемого или реорганизованного юридического лица.\n\n5. Если передаточный акт не позволяет определить правопреемника по обязательству юридического лица, а также если из передаточного акта или иных обстоятельств следует, что при реорганизации недобросовестно распределены активы и обязательства реорганизуемых юридических лиц, что привело к существенному нарушению интересов кредиторов, реорганизованное юридическое лицо и созданные в результате реорганизации юридические лица несут солидарную ответственность по такому обязательству.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 60. Гарантии прав кредиторов реорганизуемого юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"afa9ef0ca3e780a46f3e80b8e6da36a15709c35e74e04186171fd9f7a4d5433d"},{"code_id":"GK_RF","article_number":"60.1","version_date":"1994-11-30","article_text":"1. Решение о реорганизации юридического лица может быть признано недействительным по требованию участников реорганизуемого юридического лица, а также иных лиц, не являющихся участниками юридического лица, если такое право им предоставлено законом.\n\nУказанное требование может быть предъявлено в суд не позднее чем в течение трех месяцев после внесения в единый государственный реестр юридических лиц записи о начале процедуры реорганизации, если иной срок не установлен законом.\n\n2. Признание судом недействительным решения о реорганизации юридического лица не влечет ликвидации образовавшегося в результате реорганизации юридического лица, а также не является основанием для признания недействительными сделок, совершенных таким юридическим лицом.\n\n3. В случае признания решения о реорганизации юридического лица недействительным до окончания реорганизации, если осуществлена государственная регистрация части юридических лиц, подлежащих созданию в результате реорганизации, правопреемство наступает только в отношении таких зарегистрированных юридических лиц, в остальной части права и обязанности сохраняются за прежними юридическими лицами.\n\n4. Лица, недобросовестно способствовавшие принятию признанного судом недействительным решения о реорганизации, обязаны солидарно возместить убытки участнику реорганизованного юридического лица, голосовавшему против принятия решения о реорганизации или не принимавшему участия в голосовании, а также кредиторам реорганизованного юридического лица. Солидарно с данными лицами, недобросовестно способствовавшими принятию решения о реорганизации, отвечают юридические лица, созданные в результате реорганизации на основании указанного решения.\n\nЕсли решение о реорганизации юридического лица принималось коллегиальным органом, солидарная ответственность возлагается на членов этого органа, голосовавших за принятие соответствующего решения.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 60.1. Последствия признания недействительным решения о реорганизации юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aabbd8184002f6ac7ad202f48b16a5289f29b3801deede954982c8d7d7113f9a"},{"code_id":"GK_RF","article_number":"60.2","version_date":"1994-11-30","article_text":"1. Суд по требованию участника корпорации, голосовавшего против принятия решения о реорганизации этой корпорации или не принимавшего участия в голосовании по данному вопросу, может признать реорганизацию несостоявшейся в случае, если решение о реорганизации не принималось участниками реорганизованной корпорации, а также в случае представления для государственной регистрации юридических лиц, создаваемых путем реорганизации, документов, содержащих заведомо недостоверные данные о реорганизации.\n\n2. Решение суда о признании реорганизации несостоявшейся влечет следующие правовые последствия:\n\n1) восстанавливаются юридические лица, существовавшие до реорганизации, с одновременным прекращением юридических лиц, созданных в результате реорганизации, о чем делаются соответствующие записи в едином государственном реестре юридических лиц;\n\n2) сделки юридических лиц, созданных в результате реорганизации, с лицами, добросовестно полагавшимися на правопреемство, сохраняют силу для восстановленных юридических лиц, которые являются солидарными должниками и солидарными кредиторами по таким сделкам;\n\n3) переход прав и обязанностей признается несостоявшимся, при этом предоставление (платежи, услуги и т.п.), осуществленное в пользу юридического лица, созданного в результате реорганизации, должниками, добросовестно полагавшимися на правопреемство на стороне кредитора, признается совершенным в пользу управомоченного лица. Если за счет имущества (активов) одного из юридических лиц, участвовавших в реорганизации, исполнены обязанности другого из них, перешедшие к юридическому лицу, созданному в результате реорганизации, к отношениям указанных лиц применяются правила об обязательствах вследствие неосновательного обогащения (глава 60). Произведенные выплаты могут быть оспорены по заявлению лица, за счет средств которого они были произведены, если получатель исполнения знал или должен был знать о незаконности реорганизации;\n\n4) участники ранее существовавшего юридического лица признаются обладателями долей участия в нем в том размере, в котором доли принадлежали им до реорганизации, а при смене участников юридического лица в ходе такой реорганизации или по ее окончании доли участия участников ранее существовавшего юридического лица возвращаются им по правилам, предусмотренным пунктом 3 статьи 652 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 60.2. Признание реорганизации корпорации несостоявшейся","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"479c6f31c9787e7f4ef198872dd4e62803a0075d259c2fa680fc81fa47ce6d55"},{"code_id":"GK_RF","article_number":"61","version_date":"1994-11-30","article_text":"1. Ликвидация юридического лица влечет его прекращение без перехода в порядке универсального правопреемства его прав и обязанностей к другим лицам.\n\n2. Юридическое лицо ликвидируется по решению его учредителей (участников) или органа юридического лица, уполномоченного на то учредительным документом, в том числе в связи с истечением срока, на который создано юридическое лицо, с достижением цели, ради которой оно создано.\n\n3. Юридическое лицо ликвидируется по решению суда:\n\n1) по иску государственного органа или органа местного самоуправления, которым право на предъявление требования о ликвидации юридического лица предоставлено законом, в случае признания государственной регистрации юридического лица недействительной, в том числе в связи с допущенными при его создании грубыми нарушениями закона, если эти нарушения носят неустранимый характер;\n\n2) по иску государственного органа или органа местного самоуправления, которым право на предъявление требования о ликвидации юридического лица предоставлено законом, в случае осуществления юридическим лицом деятельности без надлежащего разрешения (лицензии) либо при отсутствии обязательного членства в саморегулируемой организации или необходимого в силу закона свидетельства о допуске к определенному виду работ, выданного саморегулируемой организацией;\n\n3) по иску государственного органа или органа местного самоуправления, которым право на предъявление требования о ликвидации юридического лица предоставлено законом, в случае осуществления юридическим лицом деятельности, запрещенной законом, либо с нарушением Конституции Российской Федерации, либо с другими неоднократными или грубыми нарушениями закона или иных правовых актов;\n\n4) по иску государственного органа или органа местного самоуправления, которым право на предъявление требования о ликвидации юридического лица предоставлено законом, в случае систематического осуществления общественной организацией, общественным движением, общественно полезным фондом, религиозной организацией деятельности, противоречащей уставным целям таких организаций; (В редакции  федеральных законов от 23.05.2015 № 133-ФЗ, от 08.08.2024 № 237-ФЗ)\n\n5) по иску учредителя (участника) юридического лица в случае невозможности достижения целей, ради которых оно создано, в том числе в случае, если осуществление деятельности юридического лица становится невозможным или существенно затрудняется;\n\n6) в иных случаях, предусмотренных законом.\n\n4. С момента принятия решения о ликвидации юридического лица срок исполнения его обязательств перед кредиторами считается наступившим.\n\n5. Решением суда о ликвидации юридического лица на его учредителей (участников) или на орган, уполномоченный на ликвидацию юридического лица его учредительным документом, могут быть возложены обязанности по осуществлению ликвидации юридического лица. Неисполнение решения суда является основанием для осуществления ликвидации юридического лица арбитражным управляющим (пункт 5 статьи 62) за счет имущества юридического лица. При недостаточности у юридического лица средств на расходы, необходимые для его ликвидации, эти расходы возлагаются на учредителей (участников) юридического лица солидарно (пункт 2 статьи 62).\n\n6. Юридические лица, за исключением предусмотренных статьей 65 настоящего Кодекса юридических лиц, по решению суда могут быть признаны несостоятельными (банкротами) и ликвидированы в случаях и в порядке, которые предусмотрены законодательством о несостоятельности (банкротстве).\n\nОбщие правила о ликвидации юридических лиц, содержащиеся в настоящем Кодексе, применяются к ликвидации юридического лица в порядке конкурсного производства в случаях, если настоящим Кодексом или законодательством о несостоятельности (банкротстве) не установлены иные правила.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 61. Ликвидация юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26e87903f1499122fe1d3efb0024b67cdb196d3277cc6ed94843e87f9e43df2b"},{"code_id":"GK_RF","article_number":"62","version_date":"1994-11-30","article_text":"1. Учредители (участники) юридического лица или орган, принявшие решение о ликвидации юридического лица, в течение трех рабочих дней после даты принятия данного решения обязаны сообщить в письменной форме об этом в уполномоченный государственный орган, осуществляющий государственную регистрацию юридических лиц, для внесения в единый государственный реестр юридических лиц записи о том, что юридическое лицо находится в процессе ликвидации, а также опубликовать сведения о принятии данного решения в порядке, установленном законом.\n\n2. Учредители (участники) юридического лица независимо от оснований, по которым принято решение о его ликвидации, в том числе в случае фактического прекращения деятельности юридического лица, обязаны совершить за счет имущества юридического лица действия по ликвидации юридического лица. При недостаточности имущества юридического лица учредители (участники) юридического лица обязаны совершить указанные действия солидарно за свой счет.\n\n3. Учредители (участники) юридического лица или орган, принявшие решение о ликвидации юридического лица, назначают ликвидационную комиссию (ликвидатора) и устанавливают порядок и сроки ликвидации в соответствии с законом.\n\n4. С момента назначения ликвидационной комиссии к ней переходят полномочия по управлению делами юридического лица. Ликвидационная комиссия от имени ликвидируемого юридического лица выступает в суде. Ликвидационная комиссия обязана действовать добросовестно и разумно в интересах ликвидируемого юридического лица, а также его кредиторов.\n\nЕсли ликвидационной комиссией установлена недостаточность имущества юридического лица для удовлетворения всех требований кредиторов, дальнейшая ликвидация юридического лица может осуществляться только в порядке, установленном законодательством о несостоятельности (банкротстве).\n\n5. В случае неисполнения или ненадлежащего исполнения учредителями (участниками) юридического лица обязанностей по его ликвидации заинтересованное лицо или уполномоченный государственный орган вправе потребовать в судебном порядке ликвидации юридического лица и назначения для этого арбитражного управляющего.\n\n6. При невозможности ликвидации юридического лица ввиду отсутствия средств на расходы, необходимые для его ликвидации, и невозможности возложить эти расходы на его учредителей (участников) юридическое лицо подлежит исключению из единого государственного реестра юридических лиц в порядке, установленном законом о государственной регистрации юридических лиц.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 62. Обязанности лиц, принявших решение о ликвидации юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1e7fb2370ce440a740e34e447bc316f2c6edd19ad26dc4f6d31e5e4b9873719"},{"code_id":"GK_RF","article_number":"63","version_date":"1994-11-30","article_text":"1. Ликвидационная комиссия опубликовывает в средствах массовой информации, в которых опубликовываются данные о государственной регистрации юридического лица, сообщение о его ликвидации и о поряд\n\nке и сроке заявления требований его кредиторами. Этот срок не может быть менее двух месяцев с момента опубликования сообщения о ликвидации.\n\nЛиквидационная комиссия принимает меры по выявлению кредиторов и получению дебиторской задолженности, а также уведомляет в письменной форме кредиторов о ликвидации юридического лица.\n\n2. После окончания срока предъявления требований кредиторами ликвидационная комиссия составляет промежуточный ликвидационный баланс, который содержит сведения о составе имущества ликвидируемого юридического лица, перечне требований, предъявленных кредиторами, результатах их рассмотрения, а также о перечне требований, удовлетворенных вступившим в законную силу решением суда, независимо от того, были ли такие требования приняты ликвидационной комиссией.\n\nПромежуточный ликвидационный баланс утверждается учредителями (участниками) юридического лица или органом, принявшими решение о ликвидации юридического лица. В случаях, установленных законом, промежуточный ликвидационный баланс утверждается по согласованию с уполномоченным государственным органом.\n\n3. В случае возбуждения дела о несостоятельности (банкротстве) юридического лица его ликвидация, осуществляемая по правилам настоящего Кодекса, прекращается и ликвидационная комиссия уведомляет об этом всех известных ей кредиторов. Требования кредиторов в случае прекращения ликвидации юридического лица при возбуждении дела о его несостоятельности (банкротстве) рассматриваются в порядке, установленном законодательством о несостоятельности (банкротстве).\n\n4. Если имеющиеся у ликвидируемого юридического лица (кроме учреждений) денежные средства недостаточны для удовлетворения требований кредиторов, ликвидационная комиссия осуществляет продажу имущества юридического лица, на которое в соответствии с законом допускается обращение взыскания, с торгов, за исключением объектов стоимостью не более ста тысяч рублей (согласно утвержденному промежуточному ликвидационному балансу), для продажи которых проведение торгов не требуется.\n\nВ случае недостаточности имущества ликвидируемого юридического лица для удовлетворения требований кредиторов или при наличии признаков банкротства юридического лица ликвидационная комиссия обязана обратиться в арбитражный суд с заявлением о банкротстве юридического лица, если такое юридическое лицо может быть признано несостоятельным (банкротом).\n\n5. Выплата денежных сумм кредиторам ликвидируемого юридического лица производится ликвидационной комиссией в порядке очередности, установленной статьей 64 настоящего Кодекса, в соответствии с промежуточным ликвидационным балансом со дня его утверждения.\n\n6. После завершения расчетов с кредиторами ликвидационная комиссия составляет ликвидационный баланс, который утверждается учредителями (участниками) юридического лица или органом, принявшими решение о ликвидации юридического лица. В случаях, установленных законом, ликвидационный баланс утверждается по согласованию с уполномоченным государственным органом.\n\n7. В случаях, если настоящим Кодексом предусмотрена субсидиарная ответственность собственника имущества учреждения или казенного предприятия по обязательствам этого учреждения или этого предприятия, при недостаточности у ликвидируемых учреждения или казенного предприятия имущества, на которое в соответствии с законом может быть обращено взыскание, кредиторы вправе обратиться в суд с иском об удовлетворении оставшейся части требований за счет собственника имущества этого учреждения или этого предприятия.\n\n8. Оставшееся после удовлетворения требований кредиторов имущество юридического лица передается его учредителям (участникам), имеющим вещные права на это имущество или корпоративные права в отношении юридического лица, если иное не предусмотрено законом, иными правовыми актами или учредительным документом юридического лица. При наличии спора между учредителями (участниками) относительно того, кому следует передать вещь, она продается ликвидационной комиссией с торгов. Если иное не установлено настоящим Кодексом или другим законом, при ликвидации некоммерческой организации оставшееся после удовлетворения требований кредиторов имущество направляется в соответствии с уставом некоммерческой организации на цели, для достижения которых она была создана, и (или) на благотворительные цели.\n\n9. Ликвидация юридического лица считается завершенной, а юридическое лицо - прекратившим существование после внесения сведений о его прекращении в единый государственный реестр юридических лиц в порядке, установленном законом о государственной регистрации юридических лиц.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 63. Порядок ликвидации юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f36df59310bc06ef76570fc4fbcb3b5c24e04ce24488f4dc52c2544f8a0faa86"},{"code_id":"GK_RF","article_number":"64","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\nв первую очередь удовлетворяются требования граждан, перед которыми ликвидируемое юридическое лицо несет ответственность за причинение вреда жизни или здоровью, путем капитализации соответствующих повременных платежей, о компенсации сверх возмещения вреда, причиненного вследствие разрушения, повреждения объекта капитального строительства, нарушения требований безопасности при строительстве объекта капитального строительства, требований к обеспечению безопасной эксплуатации здания, сооружения; (В редакции федеральных законов от 03.01.2006 № 6-ФЗ; от 28.11.2011 № 337-ФЗ; от 29.06.2015 № 186-ФЗ)\n\nво вторую очередь производятся расчеты по выплате выходных пособий и оплате труда лиц, работающих или работавших по трудовому договору, и по выплате вознаграждений авторам результатов интеллектуальной деятельности; (В редакции федеральных законов от 03.01.2006 № 6-ФЗ; от 18.12.2006 № 231-ФЗ)\n\nв третью очередь производятся расчеты по обязательным платежам в бюджет и во внебюджетные фонды; (В редакции Федерального закона от 03.01.2006 № 6-ФЗ)\n\nв четвертую очередь производятся расчеты с другими кредиторами. (В редакции Федерального закона от 03.01.2006 № 6-ФЗ)\n\nабзац. (Утратил силу - Федеральный закон от 03.01.2006 № 6-ФЗ)\n\nПри ликвидации банков, привлекающих средства граждан, в первую очередь удовлетворяются также требования граждан, являющихся кредиторами банков по заключенным с ними или в их пользу договорам банковского вклада или банковского счета, за исключением договоров, связанных с осуществлением гражданином предпринимательской или иной профессиональной деятельности, в части основной суммы задолженности и причитающихся процентов, требования организации, осуществляющей обязательное страхование вкладов, в связи с выплатой возмещения по вкладам в соответствии с законом о страховании вкладов граждан в банках и требования Банка России в связи с осуществлением выплат по вкладам граждан в банках в соответствии с законом. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\nТребования кредиторов о возмещении убытков в виде упущенной выгоды, о взыскании неустойки (штрафа, пени), в том числе за неисполнение или ненадлежащее исполнение обязанности по уплате обязательных платежей, удовлетворяются после удовлетворения требований кредиторов первой, второй, третьей и четвертой очереди.  (Дополнение абзацем - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\nТребования кредиторов по обязательствам, обеспеченным залогом имущества ликвидируемого юридического лица, удовлетворяются за счет средств, полученных от продажи предмета залога, преимущественно перед иными кредиторами, за исключением обязательств перед кредиторами первой и второй очереди, права требования по которым возникли до заключения соответствующего договора залога.\n\nНе удовлетворенные за счет средств, полученных от продажи предмета залога, требования кредиторов по обязательствам, обеспеченным залогом имущества ликвидируемого юридического лица, удовлетворяются в составе требований кредиторов четвертой очереди.\n\n(Пункт в редакции Федерального закона от 03.01.2006 № 6-ФЗ)\n\n1) требования кредиторов, не удовлетворенные по причине недостаточности имущества ликвидируемого юридического лица и не удовлетворенные за счет имущества лиц, несущих субсидиарную ответственность по таким требованиям, если ликвидируемое юридическое лицо в случаях, предусмотренных статьей 65 настоящего Кодекса, не может быть признано несостоятельным (банкротом);\n\n2) требования, не признанные ликвидационной комиссией, если кредиторы по таким требованиям не обращались с исками в суд;\n\n3) требования, в удовлетворении которых решением суда кредиторам отказано.\n\n(Дополнение пунктом - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\nЗаявление о назначении процедуры распределения обнаруженного имущества ликвидированного юридического лица может быть подано в течение пяти лет с момента внесения в единый государственный реестр юридических лиц сведений о прекращении юридического лица. Процедура распределения обнаруженного имущества ликвидированного юридического лица может быть назначена при наличии средств, достаточных для осуществления данной процедуры, и возможности распределения обнаруженного имущества среди заинтересованных лиц.\n\nПроцедура распределения обнаруженного имущества ликвидированного юридического лица осуществляется по правилам настоящего Кодекса о ликвидации юридических лиц.\n\n(Дополнение пунктом - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 64. Удовлетворение требований кредиторов ликвидируемого юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f9fa4758b8c113a46030a9bf2d2b1edbead93b51f06335a771a898854aac1059"},{"code_id":"GK_RF","article_number":"64.1","version_date":"1994-11-30","article_text":"1. В случае отказа ликвидационной комиссии удовлетворить требование кредитора или уклонения от его рассмотрения кредитор до утверждения ликвидационного баланса юридического лица вправе обратиться в суд с иском об удовлетворении его требования к ликвидируемому юридическому лицу. В случае удовлетворения судом иска кредитора выплата присужденной ему денежной суммы производится в порядке очередности, установленной статьей 64 настоящего Кодекса.\n\n2. Члены ликвидационной комиссии (ликвидатор) по требованию учредителей (участников) ликвидированного юридического лица или по требованию его кредиторов обязаны возместить убытки, причиненные ими учредителям (участникам) ликвидированного юридического лица или его кредиторам, в порядке и по основаниям, которые предусмотрены статьей 531 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 64.1. Защита прав кредиторов ликвидируемого юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03723cda952ad6fa6deb4e7f0fd857ec6ce8856df0718ed8e972f45658d3a4da"},{"code_id":"GK_RF","article_number":"64.2","version_date":"1994-11-30","article_text":"1. Считается фактически прекратившим свою деятельность и подлежит исключению из единого государственного реестра юридических лиц в порядке, установленном законом о государственной регистрации юридических лиц, юридическое лицо, которое в течение двенадцати месяцев, предшествующих его исключению из указанного реестра, не представляло документы отчетности, предусмотренные законодательством Российской Федерации о налогах и сборах, и не осуществляло операций хотя бы по одному банковскому счету (недействующее юридическое лицо).\n\n2. Исключение недействующего юридического лица из единого государственного реестра юридических лиц влечет правовые последствия, предусмотренные настоящим Кодексом и другими законами применительно к ликвидированным юридическим лицам.\n\n3. Исключение недействующего юридического лица из единого государственного реестра юридических лиц не препятствует привлечению к ответственности лиц, указанных в статье 531 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 64.2. Прекращение недействующего юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"527d8e38c0c33246426a83399cb1d4fb9aeee87cadda09778c43d5db9c9693c0"},{"code_id":"GK_RF","article_number":"65","version_date":"1994-11-30","article_text":"Признание юридического лица банкротом судом влечет его ликвидацию.","article_title":"Статья 65. Несостоятельность (банкротство) юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0150d1c535f9f5ace6d16ecc5bc72f7f65aac6b26435d98df4f39cf2b7dffce5"},{"code_id":"GK_RF","article_number":"65.1","version_date":"1994-11-30","article_text":"Юридические лица, учредители которых не становятся их участниками и не приобретают в них прав членства, являются унитарными юридическими лицами. К ним относятся государственные и муниципальные унитарные предприятия, общественно полезные фонды, личные фонды, учреждения, автономные некоммерческие организации, религиозные организации, государственные корпорации, публично-правовые компании. (В редакции федеральных законов от 03.07.2016 № 236-ФЗ, от 01.07.2021 № 287-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 65.1. Корпоративные и унитарные юридические лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6cb717c0371e22a0005a57849d04d4c2421050a883248702afebbe0646f18a6c"},{"code_id":"GK_RF","article_number":"65.2","version_date":"1994-11-30","article_text":"1. Участники корпорации (участники, члены, акционеры и т.п.) вправе:\n\nучаствовать в управлении делами корпорации, за исключением случая, предусмотренного пунктом 2 статьи 84 настоящего Кодекса;\n\nв случаях и в порядке, которые предусмотрены законом и учредительным документом корпорации, получать информацию о деятельности корпорации и знакомиться с ее бухгалтерской и иной документацией;\n\nобжаловать решения органов корпорации, влекущие гражданско-правовые последствия, в случаях и в порядке, которые предусмотрены законом;\n\nтребовать, действуя от имени корпорации (пункт 1 статьи 182), возмещения причиненных корпорации убытков (статья 531);\n\nоспаривать, действуя от имени корпорации (пункт 1 статьи 182), совершенные ею сделки по основаниям, предусмотренным статьей 174 настоящего Кодекса или законами о корпорациях отдельных организационно-правовых форм, и требовать применения последствий их недействительности, а также применения последствий недействительности ничтожных сделок корпорации.\n\nУчастники корпорации могут иметь и другие права, предусмотренные законом или учредительным документом корпорации.\n\n2. Участник корпорации или корпорация, требующие возмещения причиненных корпорации убытков (статья 531) либо признания сделки корпорации недействительной или применения последствий недействительности сделки, должны принять разумные меры по заблаговременному уведомлению других участников корпорации и в соответствующих случаях корпорации о намерении обратиться с такими требованиями в суд, а также предоставить им иную информацию, имеющую отношение к делу. Порядок уведомления о намерении обратиться в суд с иском может быть предусмотрен законами о корпорациях и учредительным документом корпорации.\n\nУчастники корпорации, не присоединившиеся в порядке, установленном процессуальным законодательством, к иску о возмещении причиненных корпорации убытков (статья 531) либо к иску о признании недействительной совершенной корпорацией сделки или о применении последствий недействительности сделки, в последующем не вправе обращаться в суд с тождественными требованиями, если только суд не признает причины этого обращения уважительными.\n\n3. Если иное не установлено настоящим Кодексом, участник коммерческой корпорации, утративший помимо своей воли в результате неправомерных действий других участников или третьих лиц права участия в ней, вправе требовать возвращения ему доли участия, перешедшей к иным лицам, с выплатой им справедливой компенсации, определяемой судом, а также возмещения убытков за счет лиц, виновных в утрате доли. Суд может отказать в возвращении доли участия, если это приведет к несправедливому лишению иных лиц их прав участия или повлечет крайне негативные социальные и другие публично значимые последствия. В этом случае лицу, утратившему помимо своей воли права участия в корпорации, лицами, виновными в утрате доли участия, выплачивается справедливая компенсация, определяемая судом.\n\n4. Участник корпорации обязан:\n\nучаствовать в образовании имущества корпорации в необходимом размере в порядке, способом и в сроки, которые предусмотрены настоящим Кодексом, другим законом или учредительным документом корпорации;\n\nне разглашать конфиденциальную информацию о деятельности корпорации;\n\nучаствовать в принятии корпоративных решений, без которых корпорация не может продолжать свою деятельность в соответствии с законом, если его участ\n\nие необходимо для принятия таких решений;\n\nне совершать действия, заведомо направленные на причинение вреда корпорации;\n\nне совершать действия (бездействие), которые существенно затрудняют или делают невозможным достижение целей, ради которых создана корпорация.\n\nУчастники корпорации могут нести и другие обязанности, предусмотренные законом или учредительным документом корпорации.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 65.2. Права и обязанности участников корпорации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"666f4660f146fb80cfc52b63627c6ffe42cf8331e6680623af756b6eb0bb1b8a"},{"code_id":"GK_RF","article_number":"65.3","version_date":"1994-11-30","article_text":"1. Высшим органом корпорации является общее собрание ее участников.\n\nВ некоммерческих корпорациях и производственных кооперативах с числом участников более ста высшим органом может являться съезд, конференция или иной представительный (коллегиальный) орган, определяемый их уставами в соответствии с законом. Компетенция этого органа и порядок принятия им решений определяются настоящим Кодексом, другими законами и уставом корпорации. (В редакции Федерального закона от 23.05.2015 № 133-ФЗ)\n\n2. Если иное не предусмотрено настоящим Кодексом или другим законом, к исключительной компетенции высшего органа корпорации относятся:\n\nопределение приоритетных направлений деятельности корпорации, принципов образования и использования ее имущества;\n\nутверждение и изменение устава корпорации;\n\nопределение порядка приема в состав участников корпорации и исключения из числа ее участников, кроме случаев, если такой порядок определен законом;\n\nобразование других органов корпорации и досрочное прекращение их полномочий, если уставом корпорации в соответствии с законом это правомочие не отнесено к компетенции иных коллегиальных органов корпорации;\n\nутверждение годовых отчетов и бухгалтерской (финансовой) отчетности корпорации, если уставом корпорации в соответствии с законом это правомочие не отнесено к компетенции иных коллегиальных органов корпорации;\n\nпринятие решений о создании корпорацией других юридических лиц, об участии корпорации в других юридических лицах, о создании филиалов и об открытии представительств корпорации, за исключением случаев, если уставом хозяйственного общества в соответствии с законами о хозяйственных обществах принятие таких решений по указанным вопросам отнесено к компетенции иных коллегиальных органов корпорации;\n\nпринятие решений о реорганизации и ликвидации корпорации, о назначении ликвидационной комиссии (ликвидатора) и об утверждении ликвидационного баланса;\n\nизбрание ревизионной комиссии (ревизора) и назначение аудиторской организации или индивидуального аудитора корпорации.\n\nЗаконом и учредительным документом корпорации к исключительной компетенции ее высшего органа может быть отнесено решение иных вопросов.\n\nВопросы, отнесенные настоящим Кодексом и другими законами к исключительной компетенции высшего органа корпорации, не могут быть переданы им для решения другим органам корпорации, если иное не предусмотрено настоящим Кодексом или другим законом.\n\n3. В корпорации образуется единоличный исполнительный орган (директор, генеральный директор, председатель и т.п.). Уставом корпорации может быть предусмотрено предоставление полномочий единоличного исполнительного органа нескольким лицам, действующим совместно, или образование нескольких единоличных исполнительных органов, действующих независимо друг от друга (абзац третий пункта 1 статьи 53). В качестве единоличного исполнительного органа корпорации может выступать как физическое лицо, так и юридическое лицо.\n\nВ случаях, предусмотренных настоящим Кодексом, другим законом или уставом корпорации, в корпорации образуется коллегиальный исполнительный орган (правление, дирекция и т.п.).\n\nК компетенции указанных в настоящем пункте органов корпорации относится решение вопросов, не входящих в компетенцию ее высшего органа и созданного в соответствии с пунктом 4 настоящей статьи коллегиального органа управления.\n\n4. Наряду с исполнительными органами, указанными в пункте 3 настоящей статьи, в корпорации может быть образован в случаях, предусмотренных настоящим Кодексом, другим законом или уставом корпорации, коллегиальный орган управления (наблюдательный или иной совет), контролирующий деятельность исполнительных органов корпорации и выполняющий иные функции, возложенные на него законом или уставом корпорации. Лица, осуществляющие полномочия единоличных исполнительных органов корпораций, и члены их коллегиальных исполнительных органов не могут составлять более одной четверти состава коллегиальных органов управления корпораций и не могут являться их председателями.\n\nЧлены коллегиального органа управления корпорации имеют право получать информацию о деятельности корпорации и знакомиться с ее бухгалтерской и иной документацией, требовать возмещения причиненных корпорации убытков (статья 531), оспаривать совершенные корпорацией сделки по основаниям, предусмотренным статьей 174 настоящего Кодекса или законами о корпорациях отдельных организационно-правовых форм, и требовать применения последствий их недействительности, а также требовать применения последствий недействительности ничтожных сделок корпорации в порядке, установленном пунктом 2 статьи 652 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n1. Общие положения о хозяйственных товариществах и обществах\n\n(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 65.3. Управление в корпорации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5885b6b11e1444d4df937c65d1e727a6b048ae3e2cce8b0b24ad82158a1547e1"},{"code_id":"GK_RF","article_number":"66","version_date":"1994-11-30","article_text":"1. Хозяйственными товариществами и обществами признаются корпоративные коммерческие организации с разделенным на доли (вклады) учредителей (участников) уставным (складочным) капиталом. Имущество, созданное за счет вкладов учредителей (участников), а также произведенное и приобретенное хозяйственным товариществом или обществом в процессе деятельности, принадлежит на праве собственности хозяйственному товариществу или обществу.\n\nОбъем правомочий участников хозяйственного общества определяется пропорционально их долям в уставном капитале общества. Иной объем правомочий участников непубличного хозяйственного общества может быть предусмотрен уставом общества, а также корпоративным договором при условии внесения сведений о наличии такого договора и о предусмотренном им объеме правомочий участников общества в единый государственный реестр юридических лиц.\n\nХозяйственное общество может иметь в качестве единственного участника другое хозяйственное общество, состоящее из одного лица, если иное не установлено настоящим Кодексом или другим законом. (В редакции  Федерального закона от 24.06.2025 № 178-ФЗ)\n\nУчастниками хозяйственных обществ и вкладчиками в товариществах на вере могут быть граждане и юридические лица, а также публично-правовые образования (статья 125).\n\nУчреждения могут быть участниками хозяйственных обществ и вкладчиками в товариществах на вере с разрешения собственника имущества учреждения, если иное не установлено законом.\n\nЗаконом может быть запрещено или ограничено участие отдельных категорий лиц в хозяйственных товариществах и обществах.\n\nХозяйственные товарищества и общества могут быть учредителями (участниками) других хозяйственных товариществ и обществ, за исключением случаев, предусмотренных законом.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 66. Основные положения о хозяйственных товариществах и обществах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e74c2187f22a19a617a8eda47f223df53424d60d4bb064cb04067698e0ec61c8"},{"code_id":"GK_RF","article_number":"66.1","version_date":"1994-11-30","article_text":"1. Вкладом участника хозяйственного товарищества или общества в его имущество могут быть денежные средства, вещи, доли (акции) в уставных (складочных) капиталах других хозяйственных товариществ и обществ, государственные и муниципальные облигации. Таким вкладом также могут быть подлежащие денежной оценке исключительные, иные интеллектуальные права и права по лицензионным договорам, если иное не установлено законом.\n\n2. Законом или учредительными документами хозяйственного товарищества или общества могут быть установлены виды указанного в пункте 1 настоящей статьи имущества, которое не может быть внесено для оплаты долей в уставном (складочном) капитале хозяйственного товарищества или общества.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 66.1. Вклады в имущество хозяйственного товарищества или общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"63de0cf28ee90c92000abd9a66b37f409dced58c044f37d4167a06ef7441740f"},{"code_id":"GK_RF","article_number":"66.2","version_date":"1994-11-30","article_text":"1. Минимальный размер уставных капиталов хозяйственных обществ определяется законами о хозяйственных обществах.\n\nМинимальные размеры уставных капиталов хозяйственных обществ, осуществляющих банковскую, страховую или иную подлежащую лицензированию деятельность, а также акционерных обществ, использующих открытую (публичную) подписку на свои акции, устанавливаются законами, определяющими особенности правового положения указанных хозяйственных обществ.\n\n2. При оплате уставного капитала хозяйственного общества должны быть внесены денежные средства в сумме не ниже минимального размера уставного капитала (пункт 1 настоящей статьи).\n\nДенежная оценка неденежного вклада в уставный капитал хозяйственного общества должна быть проведена независимым оценщиком. Участники хозяйственного общества не вправе определять денежную оценку неденежного вклада в размере, превышающем сумму оценки, определенную независимым оценщиком.\n\n3. При оплате долей в уставном капитале общества с ограниченной ответственностью не денежными средствами, а иным имуществом участники общества и независимый оценщик в случае недостаточности имущества общества солидарно несут субсидиарную ответственность по его обязательствам в пределах суммы, на которую завышена оценка имущества, внесенного в уставный капитал, в течение пяти лет с момента государственной регистрации общества или внесения в устав общества соответствующих изменений. При внесении в уставный капитал акционерного общества не денежных средств, а иного имущества акционер, осуществивший такую оплату, и независимый оценщик в случае недостаточности имущества общества солидарно несут субсидиарную ответственность по его обязательствам в пределах суммы, на которую завышена оценка имущества, внесенного в уставный капитал, в течение пяти лет с момента государственной регистрации общества или внесения в устав общества соответствующих изменений.\n\nПравила настоящего пункта об ответственности участника общества и независимого оценщика не применяются к хозяйственным обществам, созданным в соответствии с законами о приватизации путем приватизации государственных или муниципальных унитарных предприятий.\n\n4. Если иное не предусмотрено законами о хозяйственных обществах, учредители хозяйственного общества обязаны оплатить не менее трех четвертей его уставного капитала до государственной регистрации общества, а остальную часть уставного капитала хозяйственного общества - в течение первого года деятельности общества.\n\nВ случаях, если в соответствии с законом допускается государственная регистрация хозяйственного общества без предварительной оплаты трех четвертей уставного капитала, участники общества несут субсидиарную ответственность по его обязательствам, возникшим до момента полной оплаты уставного капитала.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 66.2. Основные положения об уставном капитале хозяйственного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"465bfe0b49bef43f2c24eec0c0d6eb6b074b19e6b405386cd11c5cb4ae5c6403"},{"code_id":"GK_RF","article_number":"66.3","version_date":"1994-11-30","article_text":"1. Публичным является акционерное общество, акции которого и ценные бумаги которого, конвертируемые в его акции, публично размещаются (путем открытой подписки) или публично обращаются на условиях, установленных законами о ценных бумагах. Правила о публичных обществах применяются также к акционерным обществам, устав и фирменное наименование которых содержат указание на то, что общество является публичным.\n\n2. Общество с ограниченной ответственностью и акционерное общество, которое не отвечает признакам, указанным в пункте 1 настоящей статьи, признаются непубличными.\n\n3. По решению участников (учредителей) непубличного общества, принятому единогласно, в устав общества могут быть включены следующие положения:\n\n1) о передаче на рассмотрение коллегиального органа управления общества (пункт 4 статьи 653) или коллегиального исполнительного органа общества вопросов, отнесенных законом к компетенции общего собрания участников хозяйственного общества, за исключением вопросов:\n\nвнесения изменений в устав хозяйственного общества, утверждения устава в новой редакции;\n\nреорганизации или ликвидации хозяйственного общества;\n\nопределения количественного состава коллегиального органа управления общества (пункт 4 статьи 653) и коллегиального исполнительного органа (если его формирование отнесено к компетенции общего собрания участников хозяйственного общества), избрания их членов и досрочного прекращения их полномочий;\n\nопределения количества, номинальной стоимости, категории (типа) объявленных акций и прав, предоставляемых этими акциями;\n\nувеличения уставного капитала общества с ограниченной ответственностью непропорционально долям его участников или за счет принятия третьего лица в состав участников такого общества;\n\nутверждения не являющихся учредительными документами внутреннего регламента или иных внутренних документов (пункт 5 статьи 52) хозяйственного общества;\n\n2) о закреплении функций коллегиального исполнительного органа общества за коллегиальным органом управления общества (пункт 4 статьи 653) полностью или в части либо об отказе от создания коллегиального исполнительного органа, если его функции осуществляются указанным коллегиальным органом управления;\n\n3) о передаче единоличному исполнительному органу общества функций коллегиального исполнительного органа общества;\n\n4) об отсутствии в обществе ревизионной комиссии или о ее создании исключительно в случаях, предусмотренных уставом общества;\n\n5) о порядке, отличном от установленного законами и иными правовыми актами порядка принятия решений о проведении заседания общего собрания или заочного голосования участников общества, порядка подготовки и проведения заседания общего собрания или заочного голосования участников общества, а также порядка принятия решений общего собрания, при условии, что такие изменения не лишают участников общества права на участие в заседании общего собрания общества или в заочном голосовании и на получение информации о них; (В редакции Федерального закона от 28.06.2021 № 225-ФЗ)\n\n6) о требованиях, отличных от установленных законами и иными правовыми актами требований к количественному составу, порядку формирования и проведения заседаний коллегиального органа управления общества (пункт 4 статьи 653) или коллегиального исполнительного органа общества;\n\n7) о порядке осуществления преимущественного права покупки доли или части доли в уставном капитале общества с ограниченной ответственностью или преимущественного права приобретения размещаемых акционерным обществом акций либо ценных бумаг, конвертируемых в его акции, а также о максимальной доле участия одного участника общества с ограниченной ответственностью в уставном капитале общества;\n\n8) об отнесении к компетенции общего собрания акционеров вопросов, не относящихся к ней в соответствии с настоящим Кодексом или законом об акционерных обществах;\n\n9) иные положения в случаях, предусмотренных законами о хозяйственных обществах.\n\n4. В случаях, если положения, предусмотренные пунктом 3 настоящей статьи, не относятся к числу положений, подлежащих в соответствии с настоящим Кодексом или другими законами обязательному включению в устав непубличного хозяйственного общества, они могут быть предусмотрены корпоративным договором, сторонами которого являются все участники этого общества.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 66.3. Публичные и непубличные общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"820b0e52dccb3e6fdf67ea7606b7b28088f91727edc0b62782ba471fe361264e"},{"code_id":"GK_RF","article_number":"67","version_date":"1994-11-30","article_text":"1. Участник хозяйственного товарищества или общества наряду с правами, предусмотренными для участников корпораций пунктом 1 статьи 652 настоящего Кодекса, также вправе:\n\nпринимать участие в распределении прибыли товарищества или общества, участником которого он является;\n\nполучать в случае ликвидации товарищества или общества часть имущества, оставшегося после расчетов с кредиторами, или его стоимость;\n\nтребовать исключения другого участника из товарищества или общества (кроме публичных акционерных обществ) в судебном порядке с выплатой ему действительной стоимости его доли участия, если такой участник своими действиями (бездействием) причинил существенный вред товариществу или обществу либо иным образом существенно затрудняет его деятельность и достижение целей, ради которых оно создавалось, в том числе грубо нарушая свои обязанности, предусмотренные законом или учредительными документами товарищества или общества. Отказ от этого права или его ограничение ничтожны.\n\nУчастники хозяйственных товариществ или обществ могут иметь и другие права, предусмотренные настоящим Кодексом, законами о хозяйственных обществах, учредительными документами товарищества или общества.\n\n2. Участник хозяйственного товарищества или общества наряду с обязанностями, предусмотренными для участников корпораций пунктом 4 статьи 652 настоящего Кодекса, также обязан вносить вклады в уставный (складочный) капитал товарищества или общества, участником которого он является, в порядке, в размерах, способами, которые предусмотрены учредительным документом хозяйственного товарищества или общества, и вклады в иное имущество хозяйственного товарищества или общества.\n\nУчастники хозяйственных товариществ и обществ могут нести и другие обязанности, предусмотренные законом и их учредительными документами.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 67. Права и обязанности участника хозяйственного товарищества и общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"85d3546c5e06ab10d43de04585c1ddbdbf80f2a2c6a7f78a04bc311ce51d2d6f"},{"code_id":"GK_RF","article_number":"67.1","version_date":"1994-11-30","article_text":"1. Управление в полном товариществе и товариществе на вере осуществляется в порядке, установленном статьями 71 и 84 настоящего Кодекса.\n\n2. К исключительной компетенции общего собрания участников хозяйственного общества наряду с вопросами, указанными в пункте 2 статьи 653 настоящего Кодекса, относятся:\n\n1) изменение размера уставного капитала общества, если иное не предусмотрено законами о хозяйственных обществах;\n\n2) принятие решения о передаче полномочий единоличного исполнительного органа общества другому хозяйст\n\nвенному обществу (управляющей организации) или индивидуальному предпринимателю (управляющему), а также утверждение такой управляющей организации или такого управляющего и условий договора с такой управляющей организацией или с таким управляющим, если уставом общества решение указанных вопросов не отнесено к компетенции коллегиального органа управления общества (пункт 4 статьи 653);\n\n3) распределение прибылей и убытков общества.\n\n1) публичного акционерного общества лицом, осуществляющим ведение реестра акционеров такого общества и выполняющим функции счетной комиссии (пункт 4 статьи 97);\n\n2) непубличного акционерного общества путем нотариального удостоверения или удостоверения лицом, осуществляющим ведение реестра акционеров такого общества и выполняющим функции счетной комиссии;\n\n3) общества с ограниченной ответственностью путем нотариального удостоверения, если иной способ (подписание протокола всеми участниками или частью участников; с использованием технических средств, позволяющих достоверно установить факт принятия решения; иным способом, не противоречащим закону) не предусмотрен уставом такого общества либо решением общего собрания участников общества, принятым участниками общества единогласно.\n\nАудит бухгалтерской (финансовой) отчетности общества с ограниченной ответственностью проводится по требованию любого из участников общества.\n\n(Пункт в редакции  Федерального закона от 16.04.2022 № 99-ФЗ)\n\nАудит бухгалтерской (финансовой) отчетности акционерного общества проводится по требованию акционеров, совокупная доля участия которых в уставном капитале общества составляет десять и более процентов, в отношении публичного акционерного общества аудиторской организацией, а в отношении непубличного акционерного общества аудиторской организацией или индивидуальным аудитором, которые должны быть независимы в соответствии с законом об аудиторской деятельности.\n\n(Пункт в редакции  Федерального закона от 16.04.2022 № 99-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 67.1. Особенности управления и контроля в хозяйственных товариществах и обществах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"227a6aa59c6e144fb0b218c51e8f48094ce4bf986436d3403eb7f079a36a8e45"},{"code_id":"GK_RF","article_number":"67.2","version_date":"1994-11-30","article_text":"Условия корпоративного договора, противоречащие правилам абзаца первого настоящего пункта, ничтожны.\n\nКорпоративным договором может быть установлена обязанность его сторон проголосовать на общем собрании участников общества за включение в устав общества положений, определяющих структуру органов общества и их компетенцию, если в соответствии с настоящим Кодексом и законами о хозяйственных обществах допускается изменение структуры органов общества и их компетенции уставом общества.\n\nИнформация о корпоративном договоре, заключенном акционерами публичного акционерного общества, должна быть раскрыта в пределах, в порядке и на условиях, которые предусмотрены законом об акционерных обществах.\n\nЕсли иное не установлено законом, информация о содержании корпоративного договора, заключенного участниками непубличного общества, не подлежит раскрытию и является конфиденциальной.\n\nПризнание решения органа хозяйственного общества недействительным в соответствии с настоящим пунктом само по себе не влечет недействительности сделок хозяйственного общества с третьими лицами, совершенных на основании такого решения.\n\nСделка, заключенная стороной корпоративного договора в нарушение этого договора, может быть признана судом недействительной по иску участника корпоративного договора только в случае, если другая сторона сделки знала или должна была знать об ограничениях, предусмотренных корпоративным договором.\n\n10. Правила о корпоративном договоре соответственно применяются к соглашению о создании хозяйственного общества, если иное не установлено законом или не вытекает из существа отношений сторон такого соглашения.\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 67.2. Корпоративный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f060b1887954aa6c2bb725ef055aac87ef2c804596d83148a7a7f2043956e245"},{"code_id":"GK_RF","article_number":"67.3","version_date":"1994-11-30","article_text":"1. Хозяйственное общество признается дочерним, если другое (основное) хозяйственное товарищество или общество в силу преобладающего участия в его уставном капитале, либо в соответствии с заключенным между ними договором, либо иным образом имеет возможность определять решения, принимаемые таким обществом.\n\n2. Дочернее общество не отвечает по долгам основного хозяйственного товарищества или общества.\n\nОсновное хозяйственное товарищество или общество отвечает солидарно с дочерним обществом по сделкам, заключенным последним во исполнение указаний или с согласия основного хозяйственного товарищества или общества (пункт 3 статьи 401), за исключением случаев голосования основного хозяйственного товарищества или общества по вопросу об одобрении сделки на общем собрании участников дочернего общества, а также одобрения сделки органом управления основного хозяйственного общества, если необходимость такого одобрения предусмотрена уставом дочернего и (или) основного общества. (В редакции Федерального закона от 29.06.2015 № 210-ФЗ)\n\nВ случае несостоятельности (банкротства) дочернего общества по вине основного хозяйственного товарищества или общества последнее несет субсидиарную ответственность по его долгам.\n\n3. Участники (акционеры) дочернего общества вправе требовать возмещения основным хозяйственным товариществом или обществом убытков, причиненных его действиями или бездействием дочернему обществу (статья 1064).\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 67.3. Дочернее хозяйственное общество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28796cacb1b8443e5c4e55f46b290f0fda7692649d7b7c3dc53078422e6ba50b"},{"code_id":"GK_RF","article_number":"69","version_date":"1994-11-30","article_text":"1. Полным признается товарищество, участники которого (полные товарищи) в соответствии с заключенным между ними договором занимаются предпринимательской деятельностью от имени товарищества и несут ответственность по его обязательствам принадлежащим им имуществом.\n\n2. Лицо может быть участником только одного полного товарищества.\n\n3. Фирменное наименование полного товарищества должно содержать либо имена (наименования) всех его участников и слова \"полное товарищество\", либо имя (наименование) одного или нескольких участников с добавлением слов \"и компания\" и слова \"полное товарищество\".","article_title":"Статья 69. Основные положения о полном товариществе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a0de696d748c176bf1774cbafe67775575113025ed09d60b902630bdf35f0ead"},{"code_id":"GK_RF","article_number":"7","version_date":"1994-11-30","article_text":"1. Общепризнанные принципы и нормы международного права и международные договоры Российской Федерации являются в соответствии с Конституцией Российской Федерации составной частью правовой системы Российской Федерации.\n\n2. Международные договоры Российской Федерации применяются к отношениям, указанным в пунктах 1 и 2 статьи 2 настоящего Кодекса, непосредственно, кроме случаев, когда из международного договора следует, что для его применения требуется издание внутригосударственного акта.\n\nЕсли международным договором Российской Федерации установлены иные правила, чем те, которые предусмотрены гражданским законодательством, применяются правила международного договора. Не допускается применение правил международных договоров Российской Федерации в их истолковании, противоречащем Конституции Российской Федерации. Такое противоречие может быть установлено в порядке, определенном федеральным конституционным законом. (В редакции Федерального закона от 08.12.2020 № 427-ФЗ)","article_title":"Статья 7. Гражданское законодательство и нормы международного права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25d76a0688a20077bfd968dbc56943366529abffea543a14beb3c52926b0d8e1"},{"code_id":"GK_RF","article_number":"70","version_date":"1994-11-30","article_text":"1. Полное товарищество создается и действует на основании учредительного договора. Учредительный договор подписывается всеми его участниками.\n\n2. Учредительный договор полного товарищества должен содержать помимо сведений, указанных в пункте 2 статьи 52 настоящего Кодекса, условия о размере и составе складочного капитала товарищества; о размере и порядке изменения долей каждого из участников в складочном капитале; о размере, составе, сроках и порядке внесения ими вкладов; об ответственности участников за нарушение обязанностей по внесению вкладов.","article_title":"Статья 70. Учредительный договор полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ccf53169b3efe82d5dbf430afc184b1a0a1bcf8f4e3e9a1faccd5da3e9b827b7"},{"code_id":"GK_RF","article_number":"71","version_date":"1994-11-30","article_text":"1. Управление деятельностью полного товарищества осуществляется по общему согласию всех участников. Учредительным договором товарищества могут быть предусмотрены случаи, когда решение принимается большинством голосов участников.\n\n2. Каждый участник полного товарищества имеет один голос, если учредительным договором не предусмотрен иной порядок определения количества голосов его участников.","article_title":"Статья 71. Управление в полном товариществе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bbe292879a7b7faaacc008f4f815d64a057e0e081047e1433292ac724beecef9"},{"code_id":"GK_RF","article_number":"72","version_date":"1994-11-30","article_text":"1. Каждый участник полного товарищества вправе действовать от имени товарищества, если учредительным договором не установлено, что все его участники ведут дела совместно, либо ведение дел поручено отдельным участникам.\n\nПри совместном ведении дел товарищества его участниками для совершения каждой сделки требуется согласие всех участников товарищества.\n\nЕсли ведение дел товарищества поручается его участниками одному или некоторым из них, остальные участники для совершения сделок от имени товарищества должны иметь доверенность от участника (участников), на которого возложено ведение дел товарищества.\n\nВ отношениях с третьими лицами товарищество не вправе ссылаться на положения учредительного договора, ограничивающие полномочия участников товарищества, за исключением случаев, когда товарищество докажет, что третье лицо в момент совершения сделки знало или заведомо должно было знать об отсутствии у участника товарищества права действовать от имени товарищества.\n\n2. Полномочия на ведение дел товарищества, предоставленные одному или нескольким участникам, могут быть прекращены судом по требованию одного или нескольких других участников товарищества при наличии к тому серьезных оснований, в частности вследствие грубого нарушения уполномоченным лицом (лицами) своих обязанностей или обнаружившейся неспособности его к разумному ведению дел. На основании судебного решения в учредительный договор товарищества вносятся необходимые изменения.","article_title":"Статья 72. Ведение дел полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6b23b508d634a3882d88bd92487a984908f71961c10fdf760bf4a94727a9aafb"},{"code_id":"GK_RF","article_number":"73","version_date":"1994-11-30","article_text":"1. Участник полного товарищества обязан участвовать в его деятельности в соответствии с условиями учредительного договора.\n\nПри нарушении этого правила товарищество вправе по своему выбору потребовать от такого участника возмещения причиненных товариществу убытков либо передачи товариществу всей приобретенной по таким сделкам выгоды.","article_title":"Статья 73. Обязанности участника полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba90a1c356e38afdf7248b91a1c5de380a555f6a95205582bb3f77ff9200e06e"},{"code_id":"GK_RF","article_number":"74","version_date":"1994-11-30","article_text":"1. Прибыль и убытки полного товарищества распределяются между его участниками пропорционально их долям в складочном капитале, если иное не предусмотрено учредительным договором или иным соглашением участников. Не допускается соглашение об устранении кого-либо из участников товарищества от участия в прибыли или в убытках.\n\n2. Если вследствие понесенных товариществом убытков стоимость его чистых активов станет меньше размера его складочного капитала, полученная товариществом прибыль не распределяется между участниками до тех пор, пока стоимость чистых активов не превысит размер складочного капитала.","article_title":"Статья 74. Распределение прибыли и убытков полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"613e63fda374f829e4b0dcfe55253bce8b96cec149e2d7dcc63c9b8d3e83168e"},{"code_id":"GK_RF","article_number":"75","version_date":"1994-11-30","article_text":"1. Участники полного товарищества солидарно несут субсидиарную ответственность своим имуществом по обязательствам товарищества.\n\n2. Участник полного товарищества, не являющийся его учредителем, отвечает наравне с другими участниками по обязательствам, возникшим до его вступления в товарищество.\n\nУчастник, выбывший из товарищества, отвечает по обязательствам товарищества, возникшим до момента его выбытия, наравне с оставшимися участниками в течение двух лет со дня утверждения отчета о деятельности товарищества за год, в котором он выбыл из товарищества.\n\n3. Соглашение участников товарищества об ограничении или устранении ответственности, предусмотренной в настоящей статье, ничтожно.","article_title":"Статья 75. Ответственность участников полного товарищества по его обязательствам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6634f8dea5d06bdbf837aee4f3a2ec47abcaf5e01dcb219c1621f81adc7b0765"},{"code_id":"GK_RF","article_number":"76","version_date":"1994-11-30","article_text":"1. В случаях выхода или смерти кого-либо из участников полного товарищества, признания одного из них безвестно отсутствующим, недееспособным, или ограниченно дееспособным, либо несостоятельным (банкротом), открытия в отношении одного из участников реорганизационных процедур по решению суда, ликвидации участвующего в товариществе юридического лица либо обращения кредитором одного из участников взыскания на часть имущества, соответствующую его доле в складочном капитале, товарищество может продолжить свою деятельность, если это предусмотрено учредительным договором товарищества или соглашением остающихся участников.\n\n2. Участники полного товарищества вправе требовать в судебном порядке исключения кого-либо из участников из товарищества по единогласному решению остающихся участников и при наличии к тому серьезных оснований, в частности вследствие грубого нарушения этим участником своих обязанностей или обнаружившейся неспособности его к разумному ведению дел.","article_title":"Статья 76. Изменение состава участников полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"edd539de5adc3cd8aa325ec3a4a0db2a22666583dffefdb8f919b8b0420cbc84"},{"code_id":"GK_RF","article_number":"77","version_date":"1994-11-30","article_text":"1. Участник полного товарищества вправе выйти из него, заявив об отказе от участия в товариществе.\n\nОтказ от участия в полном товариществе, учрежденном без указания срока, должен быть заявлен участником не менее чем за шесть месяцев до фактического выхода из товарищества. Досрочный отказ от участия в полном товариществе, учрежденном на определенный срок, допускается лишь по уважительной причине.\n\n2. Соглашение между участниками товарищества об отказе от права выйти из товарищества ничтожно.","article_title":"Статья 77. Выход участника из полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ac6aa31c5a356d9a6a7d75549b7d14130dc0311412f9d4410d4a7624a95588b5"},{"code_id":"GK_RF","article_number":"78","version_date":"1994-11-30","article_text":"1. Участнику, выбывшему из полного товарищества, выплачивается стоимость части имущества товарищества, соответствующей доле этого участника в складочном капитале, если иное не предусмотрено учредительным договором. По соглашению выбывающего участника с остающимися участниками выплата стоимости имущества может быть заменена выдачей имущества в натуре.\n\nПричитающаяся выбывающему участнику часть имущества товарищества или ее стоимость определяется по балансу, составляемому, за исключением случая, предусмотренного в статье 80 настоящего Кодекса, на момент его выбытия.\n\n2. В случае смерти участника полного товарищества его наследник может вступить в полное товарищество лишь с согласия других участников.\n\nЮридическое лицо, являющееся правопреемником участвовавшего в полном товариществе реорганизованного юридического лица, вправе вступить в товарищество с согласия других его участников, если иное не предусмотрено учредительным договором товарищества.\n\nРасчеты с наследником (правопреемником), не вступившим в товарищество, производятся в соответствии с пунктом 1 настоящей статьи. Наследник (правопреемник) участника полного товарищества несет ответственность по обязат\n\nельствам товарищества перед третьими лицами, по которым в соответствии с пунктом 2 статьи 75 настоящего Кодекса отвечал бы выбывший участник, в пределах перешедшего к нему имущества выбывшего участника товарищества.\n\n3. Если один из участников выбыл из товарищества, доли оставшихся участников в складочном капитале товарищества соответственно увеличиваются, если иное не предусмотрено учредительным договором или иным соглашением участников.","article_title":"Статья 78. Последствия выбытия участника из полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d18db6e7d8cc2610de401447610f771b1599707c8ff7961b60c3938f545a8dc"},{"code_id":"GK_RF","article_number":"79","version_date":"1994-11-30","article_text":"Участник полного товарищества вправе с согласия остальных его участников передать свою долю в складочном капитале или ее часть другому участнику товарищества либо третьему лицу.\n\nПри передаче доли (части доли) иному лицу к нему переходят полностью или в соответствующей части права, принадлежавшие участнику, передавшему долю (часть доли). Лицо, которому передана доля (часть доли), несет ответственность по обязательствам товарищества в порядке, установленном абзацем первым пункта 2 статьи 75 настоящего Кодекса.\n\nПередача всей доли иному лицу участником товарищества прекращает его участие в товариществе и влечет последствия, предусмотренные пунктом 2 статьи 75 настоящего Кодекса.","article_title":"Статья 79. Передача доли участника в складочном капитале полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b999a03d3b0a9ee02be3d171575f19b832e477720704c91b613b1385b2bb1772"},{"code_id":"GK_RF","article_number":"8","version_date":"1994-11-30","article_text":"1. Гражданские права и обязанности возникают из оснований, предусмотренных законом и иными правовыми актами, а также из действий граждан и юридических лиц, которые хотя и не предусмотрены законом или такими актами, но в силу общих начал и смысла гражданского законодательства порождают гражданские права и обязанности.\n\nВ соответствии с этим гражданские права и обязанности возникают:\n\n1) из договоров и иных сделок, предусмотренных законом, а также из договоров и иных сделок, хотя и не предусмотренных законом, но не противоречащих ему;\n\n11) из решений собраний в случаях, предусмотренных законом; (Дополнение подпунктом - Федеральный закон от 30.12.2012 № 302-ФЗ)\n\n2) из актов государственных органов и органов местного самоуправления, которые предусмотрены законом в качестве основания возникновения гражданских прав и обязанностей;\n\n3) из судебного решения, установившего гражданские права и обязанности;\n\n4) в результате приобретения имущества по основаниям, допускаемым законом;\n\n5) в результате создания произведений науки, литературы, искусства, изобретений и иных результатов интеллектуальной деятельности;\n\n6) вследствие причинения вреда другому лицу;\n\n7) вследствие неосновательного обогащения;\n\n8) вследствие иных действий граждан и юридических лиц;\n\n9) вследствие событий, с которыми закон или иной правовой акт связывает наступление гражданско-правовых последствий.","article_title":"Статья 8. Основания возникновения гражданских прав и обязанностей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24e1d8ceb81040364a2f8a581c015679ae91250671f008911cae3ede88d2fff1"},{"code_id":"GK_RF","article_number":"80","version_date":"1994-11-30","article_text":"Обращение взыскания на долю участника в складочном капитале полного товарищества по собственным долгам участника допускается лишь при недостатке иного его имущества для покрытия долгов. Кредиторы такого участника вправе потребовать от полного товарищества выдела части имущества товарищества, соответствующей доле должника в складочном капитале, с целью обращения взыскания на это имущество. Подлежащая выделу часть имущества товарищества или его стоимость определяется по балансу, составленному на момент предъявления кредиторами требования о выделе.\n\nОбращение взыскания на имущество, соответствующее доле участника в складочном капитале полного товарищества, прекращает его участие в товариществе и влечет последствия, предусмотренные абзацем вторым пункта 2 статьи 75 настоящего Кодекса.","article_title":"Статья 80. Обращение взыскания на долю участника в складочном капитале полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eeec8e0962eb561b64ab6da14c80ed7c396d9bde2a93e4445f6ec3447dcbc2e7"},{"code_id":"GK_RF","article_number":"8.1","version_date":"1994-11-30","article_text":"1. В случаях, предусмотренных законом, права, закрепляющие принадлежность объекта гражданских прав определенному лицу, ограничения таких прав и обременения имущества (права на имущество) подлежат государственной регистрации.\n\nГосударственная регистрация прав на имущество осуществляется уполномоченным в соответствии с законом органом на основе принципов проверки законности оснований регистрации, публичности и достоверности государственного реестра.\n\nВ государственном реестре должны быть указаны данные, позволяющие определенно установить объект, на который устанавливается право, управомоченное лицо, содержание права, основание его возникновения.\n\n2. Права на имущество, подлежащие государственной регистрации, возникают, изменяются и прекращаются с момента внесения соответствующей записи в государственный реестр, если иное не установлено законом.\n\n3. В случаях, предусмотренных законом или соглашением сторон, сделка, влекущая возникновение, изменение или прекращение прав на имущество, которые подлежат государственной регистрации, должна быть нотариально удостоверена.\n\nЗапись в государственный реестр вносится при наличии заявлений об этом всех лиц, совершивших сделку, если иное не установлено законом. Если сделка совершена в нотариальной форме, запись в государственный реестр может быть внесена по заявлению любой стороны сделки, в том числе через нотариуса.\n\n4. Если право на имущество возникает, изменяется или прекращается вследствие наступления обстоятельств, указанных в законе, запись о возникновении, об изменении или о прекращении этого права вносится в государственный реестр по заявлению лица, для которого наступают такие правовые последствия. Законом может быть предусмотрено также право иных лиц обращаться с заявлением о внесении соответствующей записи в государственный реестр.\n\nЕсли право на имущество возникает, изменяется или прекращается на основании нотариально удостоверенной сделки, уполномоченный в соответствии с законом орган вправе проверить законность соответствующей сделки в случаях и в порядке, которые предусмотрены законом.\n\nПри возникновении спора в отношении зарегистрированного права лицо, которое знало или должно было знать о недостоверности данных государственного реестра, не вправе ссылаться на соответствующие данные.\n\nПриобретатель недвижимого имущества, полагавшийся при его приобретении на данные государственного реестра, признается добросовестным (статьи 234 и 302), пока в судебном порядке не доказано, что он знал или должен был знать об отсутствии права на отчуждение этого имущества у лица, от которого ему перешли права на него. (Дополнение абзацем - Федеральный закон от 16.12.2019 № 430-ФЗ)\n\nЕсли в течение трех месяцев со дня внесения в государственный реестр отметки о возражении в отношении зарегистрированного права лицо, по заявлению которого она внесена, не оспорило зарегистрированное право в суде, отметка о возражении аннулируется. В этом случае повторное внес\n\nение отметки о возражении указанного лица не допускается.\n\nЛицо, оспаривающее зарегистрированное право в суде, вправе требовать внесения в государственный реестр отметки о наличии судебного спора в отношении этого права.\n\n(Дополнение статьей - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 8.1. Государственная регистрация прав на имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a3bb8bb9e1f7f08ad24566669c760918b821d5a71999b04ba998277579a7651d"},{"code_id":"GK_RF","article_number":"81","version_date":"1994-11-30","article_text":"Полное товарищество ликвидируется по основаниям, указанным в статье 61 настоящего Кодекса, а также в случае, когда в товариществе остается единственный участник. Такой участник вправе в течение шести месяцев с момента, когда он стал единственным участником товарищества, преобразовать такое товарищество в хозяйственное общество в порядке, установленном настоящим Кодексом.\n\nПолное товарищество ликвидируется также в случаях, указанных в пункте 1 статьи 76 настоящего Кодекса, если учредительным договором товарищества или соглашением остающихся участников не предусмотрено, что товарищество продолжит свою деятельность.","article_title":"Статья 81. Ликвидация полного товарищества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fcd5bf2423556fdf9ffe62ff40bee0ee9362004305e85b589d851bec7fef8465"},{"code_id":"GK_RF","article_number":"82","version_date":"1994-11-30","article_text":"1. Товариществом на вере (коммандитным товариществом) признается товарищество, в котором наряду с участниками, осуществляющими от имени товарищества предпринимательскую деятельность и отвечающими по обязательствам товарищества своим имуществом (полными товарищами), имеется один или несколько участников - вкладчиков (коммандитистов), которые несут риск убытков, связанных с деятельностью товарищества, в пределах сумм внесенных ими вкладов и не принимают участия в осуществлении товариществом предпринимательской деятельности.\n\n2. Положение полных товарищей, участвующих в товариществе на вере, и их ответственность по обязательствам товарищества определяются правилами настоящего Кодекса об участниках полного товарищества.\n\n3. Лицо может быть полным товарищем только в одном товариществе на вере.\n\nУчастник полного товарищества не может быть полным товарищем в товариществе на вере.\n\nПолный товарищ в товариществе на вере не может быть участником полного товарищества.\n\nЧисло коммандитистов в товариществе на вере не должно превышать двадцать. В противном случае оно подлежит преобразованию в хозяйственное общество в течение года, а по истечении этого срока - ликвидации в судебном порядке, если число его коммандитистов не уменьшится до указанного предела. (Дополнение абзацем - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n4. Фирменное наименование товарищества на вере должно содержать либо имена (наименования) всех полных товарищей и слова \"товарищество на вере\" или \"коммандитное товарищество\", либо имя (наименование) не менее чем одного полного товарища с добавлением слов \"и компания\" и слова \"товарищество на вере\" или \"коммандитное товарищество\".\n\nЕсли в фирменное наименование товарищества на вере включено имя вкладчика, такой вкладчик становится полным товарищем.\n\n5. К товариществу на вере применяются правила настоящего Кодекса о полном товариществе постольку, поскольку это не противоречит правилам настоящего Кодекса о товариществе на вере.","article_title":"Статья 82. Основные положения о товариществе на вере","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2ce76a04f1a656de68a90fdfedb6a0ecdbae224ca3f6ec4277928c54bc8452cf"},{"code_id":"GK_RF","article_number":"83","version_date":"1994-11-30","article_text":"1. Товарищество на вере создается и действует на основании учредительного договора. Учредительный договор подписывается всеми полными товарищами.\n\n2. Учредительный договор товарищества на вере должен содержать помимо сведений, указанных в пункте 2 статьи 52 настоящего Кодекса, условия о размере и составе складочного капитала товарищества; о размере и порядке изменения долей каждого из полных товарищей в складочном капитале; о размере, составе, сроках и порядке внесения ими вкладов, их ответственности за нарушение обязанностей по внесению вкладов; о совокупном размере вкладов, вносимых вкладчиками.","article_title":"Статья 83. Учредительный договор товарищества на вере","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2c6f3530b238e71c0dc17248817725865786dc490d87d49284c82f5be25fd148"},{"code_id":"GK_RF","article_number":"84","version_date":"1994-11-30","article_text":"1. Управление деятельностью товарищества на вере осуществляется полными товарищами. Порядок управления и ведения дел такого товарищества его полными товарищами устанавливается ими по правилам настоящего Кодекса о полном товариществе.\n\n2. Вкладчики не вправе участвовать в управлении и ведении дел товарищества на вере, выступать от его имени иначе, как по доверенности. Они не вправе оспаривать действия полных товарищей по управлению и ведению дел товарищества.","article_title":"Статья 84. Управление в товариществе на вере и ведение его дел","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d01460d17bcbc7398421f180d10844f1be5219fd78ff6f29898e1f788d3ff884"},{"code_id":"GK_RF","article_number":"85","version_date":"1994-11-30","article_text":"1. Вкладчик товарищества на вере обязан внести вклад в складочный капитал. Внесение вклада удостоверяется свидетельством об участии, выдаваемым вкладчику товариществом.\n\n2. Вкладчик товарищества на вере имеет право:\n\n1) получать часть прибыли товарищества, причитающуюся на его долю в складочном капитале, в порядке, предусмотренном учредительным договором;\n\n2) знакомиться с годовыми отчетами и балансами товарищества;\n\n3) по окончании финансового года выйти из товарищества и получить свой вклад в порядке, предусмотренном учредительным договором;\n\n4) передать свою долю в складочном капитале или ее часть другому вкладчику или третьему лицу. Вкладчики пользуются преимущественным перед третьими лицами правом покупки доли (ее части) применительно к условиям и порядку, предусмотренным пунктом 2 статьи 93 настоящего Кодекса. Передача всей доли иному лицу вкладчиком прекращает его участие в товариществе.\n\nУчредительным договором товарищества на вере могут предусматриваться и иные права вкладчика.","article_title":"Статья 85. Права и обязанности вкладчика товарищества на вере","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"39e1c0c67410bcd6a258591940ff9e31aabeb12ca8cc403525936c6ce490be53"},{"code_id":"GK_RF","article_number":"86","version_date":"1994-11-30","article_text":"1. Товарищество на вере ликвидируется при выбытии всех участвовавших в нем вкладчиков. Однако полные товарищи вправе вместо ликвидации преобразовать товарищество на вере в полное товарищество.\n\nТоварищество на вере ликвидируется также по основаниям ликвидации полного товарищества (статья 81). Однако товарищество на вере сохраняется, если в нем остаются по крайней мере один полный товарищ и один вкладчик.\n\n2. При ликвидации товарищества на вере, в том числе в случае банкротства, вкладчики имеют преимущественное перед полными товарищами право на получение вкладов из имущества товарищества, оставшегося после удовлетворения требований его кредиторов.\n\nОставшееся после этого имущество товарищества распределяется между полными товарищами и вкладчиками пропорционально их долям в складочном капитале товарищества, если иной порядок не установлен учредительным договором или соглашением полных товарищей и вкладчиков.\n\n31. Крестьянское (фермерское) хозяйство\n\n(Дополнение подпараграфом - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 86. Ликвидация товарищества на вере","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"18e41d6719fdadfc3b2f61aefb0d131219bb492c2d9ec7f6776f28af4b506319"},{"code_id":"GK_RF","article_number":"86.1","version_date":"1994-11-30","article_text":"1. Граждане, ведущие совместную деятельность в области сельского хозяйства без образования юридического лица на основе соглашения о создании крестьянского (фермерского) хозяйства (статья 23), вправе создать юридическое лицо - крестьянское (фермерское) хозяйство.\n\nКрестьянским (фермерским) хозяйством, создаваемым в соответствии с настоящей статьей в качестве юридического лица, признается добровольное объединение граждан на основе членства для совместной производственной или иной хозяйственной деятельности в области сельского хозяйства, основанной на их личном участии и объединении членами крестьянского (фермерского) хозяйства имущественных вкладов.\n\n2. Имущество крестьянского (фермерского) хозяйства принадлежит ему на праве собственности.\n\n3. Гражданин может быть членом только одного крестьянского (фермерского) хозяйства, созданного в качестве юридического лица.\n\n4. При обращении взыскания кредиторов крестьянского (фермерского) хозяйства на земельный участок, находящийся в собственности хозяйства, земельный участок подлежит продаже с публичных торгов в пользу лица, которое в соответствии с законом вправе продолжать использование земельного участка по целевому назначению.\n\nЧлены крестьянского (фермерского) хозяйства, созданного в качестве юридического лица, несут по обязательствам крестьянского (фермерского) хозяйства субсидиарную ответственность.\n\n5. Особенности правового положения крестьянского (фермерского) хозяйства, созданного в качестве юридического лица, определяются законом.\n\n4. Общество с ограниченной ответственностью","article_title":"Статья 86.1. Крестьянское (фермерское) хозяйство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d5eece3b92f9db2d31a13a3b559475b4aa8874cfc912342fd4b44156ee4901a7"},{"code_id":"GK_RF","article_number":"87","version_date":"1994-11-30","article_text":"Участники общества, не полностью оплатившие доли, несут солидарную ответственность по обязательствам общества в пределах стоимости неоплаченной части доли каждого из участников.\n\n(Пункт в редакции Федерального закона от 30.12.2008 № 312-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 08.07.1999 № 138-ФЗ) (Утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 87. Основные положения об обществе с ограниченной ответственностью","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3a2989a980f4758cf46409de30030c0decd7d5aabba4d5b6643b6352d516674"},{"code_id":"GK_RF","article_number":"88","version_date":"1994-11-30","article_text":"Абзац. (Утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n(Пункт в редакции Федерального закона от 30.12.2008 № 312-ФЗ)","article_title":"Статья 88. Участники общества с ограниченной ответственностью","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2245739579907b9044981b5aed060a3b11db227f5085b5533d9c3f9c16a24f12"},{"code_id":"GK_RF","article_number":"89","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n1. Учредители общества с ограниченной ответственностью заключают между собой договор об учреждении общества с ограниченной ответственностью, определяющий порядок осуществления ими совместной деятельности по учреждению общества, размер уставного капитала общества, размер их долей в уставном капитале общества и иные установленные законом об обществах с ограниченной ответственностью условия.\n\nДоговор об учреждении общества с ограниченной ответственностью заключается в письменной форме.\n\n2. Учредители общества с ограниченной ответственностью несут солидарную ответственность по обязательствам, связанным с его учреждением и возникшим до его государственной регистрации.\n\nОбщество с ограниченной ответственностью несет ответственность по обязательствам учредителей общества, связанным с его учреждением, только в случае последующего одобрения действий учредителей общества общим собранием участников общества. Размер ответственности общества по этим обязательствам учредителей общества может быть ограничен законом об обществах с ограниченной ответственностью.\n\n3. Учредительным документом общества с ограниченной ответственностью является его устав.\n\nУстав общества с ограниченной ответственностью должен содержать сведения о фирменном наименовании общества и месте его нахождения, размере его уставного капитала (за исключением случая, предусмотренного пунктом 2 статьи 52 настоящего Кодекса), составе и компетенции его органов, порядке принятия ими решений (в том числе решений по вопросам, принимаемым единогласно или квалифицированным большинством голосов) и иные сведения, предусмотренные законом об обществах с ограниченной ответственностью. (В редакции федеральных законов от 05.05.2014 № 99-ФЗ; от 29.06.2015 № 209-ФЗ)\n\n4. Порядок совершения иных действий по учреждению общества с ограниченной ответственностью определяется законом об обществах с ограниченной ответственностью.\n\n(Статья в редакции Федерального закона от 30.12.2008 № 312-ФЗ)","article_title":"Статья 89. Создание общества с ограниченной ответственностью и его устав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ec8a8208cd4f0ffa2bd91a602112a0e6ad31afb10702d2edabfcf0f18626a5b6"},{"code_id":"GK_RF","article_number":"9","version_date":"1994-11-30","article_text":"1. Граждане и юридические лица по своему усмотрению осуществляют принадлежащие им гражданские права.\n\n2. Отказ граждан и юридических лиц от осуществления принадлежащих им прав не влечет прекращения этих прав, за исключением случаев, предусмотренных законом.","article_title":"Статья 9. Осуществление гражданских прав","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6913f2fe74f3efc47ff056640e7d9ff9fc65d9747b04576a2e5479bd5eda919"},{"code_id":"GK_RF","article_number":"90","version_date":"1994-11-30","article_text":"Оплата уставного капитала общества с ограниченной ответственностью при увеличении уставного капитала путем зачета требований к обществу допускается в случаях, предусмотренных законом об обществах с ограниченной ответственностью.\n\n(Пункт в редакции Федерального закона от 27.12.2009 № 352-ФЗ)\n\nПоследствия нарушения участниками общества сроков и порядка оплаты уставного капитала общества определяются законом об обществах с ограниченной ответственностью.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 129-ФЗ)\n\nПрава и обязанности кредиторов кредитных организаций и некредитных финансовых организаций, созданных в организационно-правовой форме общества с ограниченной ответственностью, определяются также законами, регулирующими деятельность таких организаций.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 90. Уставный капитал общества с ограниченной ответственностью","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8928252e19fcb986bdde6336bcc419b4d3d8ec8fee15a206f64cb79310d547e0"},{"code_id":"GK_RF","article_number":"91","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 91. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96fba3f60695998f879bdbc9750258cddcd5503f2d24a982065cb51d24eabbc0"},{"code_id":"GK_RF","article_number":"92","version_date":"1994-11-30","article_text":"1. Общество с ограниченной ответственностью может быть реорганизовано или ликвидировано добровольно по единогласному решению его участников.\n\nИные основания реорганизации и ликвидации общества, а также порядок его реорганизации и ликвидации определяются настоящим Кодексом и другими законами.","article_title":"Статья 92. Реорганизация и ликвидация общества с ограниченной ответственностью","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a4e94b0f43729822f44135c7e89f8e410f96377ead7e28a26ac077376f20c94a"},{"code_id":"GK_RF","article_number":"93","version_date":"1994-11-30","article_text":"1. Переход доли или части доли участника общества в уставном капитале общества с ограниченной ответственностью к другому лицу допускается на основании сделки или в порядке правопреемства либо на ином законном основании с учетом особенностей, предусмотренных настоящим Кодексом и законом об обществах с ограниченной ответственностью.\n\n2. Продажа либо отчуждение иным образом доли или части доли в уставном капитале общества с ограниченной ответственностью третьим лицам допускается с соблюдением требований, предусмотренных законом об обществах с ограниченной ответственностью, если это не запрещено уставом общества.\n\nУчастники общества пользуются преимущественным правом покупки доли или части доли участника общества, если уставом общества не предусмотрено иное. Порядок осуществления преимущественного права и срок, в течение которого участники общества могут воспользоваться указанным правом, определяются законом об обществах с ограниченной ответственностью и уставом общества. Уставом общества также может быть предусмотрено преимущественное право покупки обществом доли или части доли участника общества, если другие участники общества не использовали свое преимущественное право покупки доли или части доли в уставном капитале общества. (В редакции  Федерального закона от 07.07.2025 № 185-ФЗ)\n\nкапитал в соответствии с пунктами 4 и 5 статьи 90 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 30.12.2008 № 312-ФЗ)","article_title":"Статья 93. Переход доли в уставном капитале общества с ограниченной ответственностью к другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37f158dcdf8c597976b4629d102734c5055398d44fa2c53874b18c377186fdb7"},{"code_id":"GK_RF","article_number":"94","version_date":"1994-11-30","article_text":"1. Участник общества с ограниченной ответственностью вправе выйти из общества независимо от согласия других его участников или общества путем:\n\n1) подачи заявления о выходе из общества, если такая возможность предусмотрена уставом общества;\n\n2) предъявления к обществу требования о приобретении обществом доли в случаях, предусмотренных пунктом 3 статьи 93 настоящего Кодекса и законом об обществах с ограниченной ответственностью. (В редакции Федерального закона от 23.05.2018 № 116-ФЗ)\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n(Подпараграф утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 94. Выход участника общества с ограниченной ответственностью из общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"327d4fc5175e4a997e437940d50e4df9dc3a6bf1f06328060801ecce7bbb5708"},{"code_id":"GK_RF","article_number":"96","version_date":"1994-11-30","article_text":"Акционеры, не полностью оплатившие акции, несут солидарную ответственность по обязательствам акционерного общества в пределах неоплаченной части стоимости принадлежащих им акций.\n\nОсобенности правового положения акционерных обществ, созданных путем приватизации государственных и муниципальных предприятий, определяются также законами и иными правовыми актами о приватизации этих предприятий.\n\nОсобенности правового положения кредитных организаций, созданных в организационно-правовой форме акционерного общества, права и обязанности их акционеров определяются также законами, регулирующими деятельность кредитных организаций. (Дополнение абзацем - Федеральный закон от 08.07.1999 № 138-ФЗ) (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 96. Основные положения об акционерном обществе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"483c32033b9dc939e9d4d90fecfe2fe8782bba03cbcc6b0b79426b2682b4fe64"},{"code_id":"GK_RF","article_number":"97","version_date":"1994-11-30","article_text":"1. Публичное акционерное общество (пункт 1 статьи 663) обязано представить для внесения в единый государственный реестр юридических лиц сведения о фирменном наименовании общества, содержащем указание на то, что такое общество является публичным.\n\nАкционерное общество вправе представить для внесения в единый государственный реестр юридических лиц сведения о фирменном наименовании общества, содержащем указание на то, что такое общество является публичным.\n\nАкционерное общество приобретает право публично размещать (путем открытой подписки) акции и ценные бумаги, конвертируемые в его акции, которые могут публично обращаться на условиях, установленных законами о ценных бумагах, со дня внесения в единый государственный реестр юридических лиц сведений о фирменном наименовании общества, содержащем указание на то, что такое общество является публичным.\n\n2. Приобретение непубличным акционерным обществом статуса публичного общества (пункт 1 настоящей статьи) влечет недействительность положений устава и внутренних документов общества, противоречащих правилам о публичном акционерном обществе, установленным настоящим Кодексом, законом об акционерных обществах и законами о ценных бумагах.\n\n3. В публичном акционерном обществе образуется коллегиальный орган управления общества (пункт 4 статьи 653), число членов которого не может быть менее пяти. Порядок образования и компетенция указанного коллегиального органа управления определяются законом об акционерных обществах и уставом публичного акционерного общества.\n\nУставом публичного акционерного общества не может быть отнесено к исключительной компетенции общего собрания акционеров решение вопросов, не относящихся к ней в соответствии с настоящим Кодексом и законом об акционерных обществах.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 97. Публичное акционерное общество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b5d7952c9449261719747114920395dbe5d13651d759912ab4e7017eb004a009"},{"code_id":"GK_RF","article_number":"98","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n1. Учредители акционерного общества заключают между собой договор, определяющий порядок осуществления ими совместной деятельности по созданию общества, размер уставного капитала общества, категории выпускаемых акций и порядок их размещения, а также иные условия, предусмотренные законом об акционерных обществах.\n\nДоговор о создании акционерного общества заключается в письменной форме путем составления одного документа, подписанного сторонами. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\n2. Учредители акционерного общества несут солидарную ответственность по обязательствам, возникшим до регистрации общества.\n\nОбщество несет ответственность по обязательствам учредителей, связанным с его созданием, только в случае последующего одобрения их действий общим собранием акционеров.\n\n3. Учредительным документом акционерного общества является его устав, утвержденный учредителями.\n\nУстав акционерного общества должен содержать сведения о фирменном наименовании общества и месте его нахождения, сведения о категориях выпускаемых обществом акций, об их номинальной стоимости и количестве, о размере уставного капитала общества, правах акционеров - владельцев привилегированных акций каждого типа, составе и компетенции органов общества, а также о порядке принятия ими решений. В уставе акционерного общества также должны содержаться иные сведения, предусмотренные законом. (В редакции Федерального закона от 25.02.2022 № 20-ФЗ)\n\n4. Порядок совершения иных действий по созданию акционерного общества, в том числе компетенция учредительного собрания, определяется законом об акционерных обществах.\n\n5. Особенности создания акционерных обществ при приватизации государственных и муниципальных предприятий определяются законами и иными правовыми актами о приватизации этих предприятий.\n\n6. Акционерное общество может быть создано одним лицом или состоять из одного лица в случае приобретения одним акционером всех акций общества. Сведения об этом подлежат внесению в единый государственный реестр юридических лиц.\n\nАкционерное общество может иметь в качестве единственного участника другое хозяйственное общество, состоящее из одного лица, если иное не установлено законом. (В редакции Федерального закона  от 24.06.2025 № 178-ФЗ)\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 98. Создание акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b0e78198060d7669b4f31b220d739817f862b6ab03a4b1fda31478d9871be37"},{"code_id":"GK_RF","article_number":"99","version_date":"1994-11-30","article_text":"1. Уставный капитал акционерного общества составляется из номинальной стоимости акций общества, приобретенных акционерами.\n\nАбзац. (Утратил силу - Федеральный закон от 05.05.2014 № 99-ФЗ)\n\n2. Не допускается освобождение акционера от обязанности оплаты акций общества.\n\nОплата размещаемых обществом дополнительных акций путем зачета требований к обществу допускается в случаях, предусмотренных законом об акционерных обществах.\n\n(Пункт в редакции Федерального закона от 27.12.2009 № 352-ФЗ)\n\n3. Открытая подписка на акции акционерного общества не допускается до полной оплаты уставного капитала. При учреждении акционерного общества все его акции должны быть распределены среди учредителей.","article_title":"Статья 99. Уставный капитал акционерного общества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca735b954ddb961c851d99055829f770549bc38f4da5d7290090035c72828286"},{"code_id":"GK_RF_2","article_number":"1000","version_date":"1994-11-30","article_text":"Комитент обязан:\n\nпринять от комиссионера все исполненное по договору комиссии;\n\nосмотреть имущество, приобретенное для него комиссионером, и известить последнего без промедления об обнаруженных в этом имуществе недостатках;\n\nосвободить комиссионера от обязательств, принятых им на себя перед третьим лицом по исполнению комиссионного поручения.","article_title":"Статья 1000. Принятие комитентом исполненного по договору комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7c0fd9d241ed8c18899f614a8b3262b2ce7cd7288fac6ee7f58ffdde98c78794"},{"code_id":"GK_RF_2","article_number":"1001","version_date":"1994-11-30","article_text":"Комитент обязан помимо уплаты комиссионного вознаграждения, а в соответствующих случаях и дополнительного вознаграждения за делькредере возместить комиссионеру израсходованные им на исполнение комиссионного поручения суммы.\n\nКомиссионер не имеет права на возмещение расходов на хранение находящегося у него имущества комитента, если в законе или договоре комиссии не установлено иное.","article_title":"Статья 1001. Возмещение расходов на исполнение комиссионного поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ef00bc75b9a739a7f03036e378b6c53eb2752d885ceeee565a26d2816c65378"},{"code_id":"GK_RF_2","article_number":"1002","version_date":"1994-11-30","article_text":"Договор комиссии прекращается вследствие:\n\nотказа комитента от исполнения договора;\n\nотказа комиссионера от исполнения договора в случаях, предусмотренных законом или договором;\n\nсмерти комиссионера, признания его недееспособным, ограниченно дееспособным или безвестно отсутствующим;\n\nпризнания индивидуального предпринимателя, являющегося комиссионером, несостоятельным (банкротом).\n\nВ случае объявления комиссионера несостоятельным (банкротом) его права и обязанности по сделкам, заключенным им для комитента во исполнение указаний последнего, переходят к комитенту.","article_title":"Статья 1002. Прекращение договора комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff24948bd647a6037339dfd55c28332de07f51fd7d95ff78c8849d801f479f2c"},{"code_id":"GK_RF_2","article_number":"1003","version_date":"1994-11-30","article_text":"1. Комитент вправе в любое время отказаться от исполнения договора комиссии, отменив данное комиссионеру поручение. Комиссионер вправе требовать возмещения убытков, вызванных отменой поручения.\n\n2. В случае, когда договор комиссии заключен без указания срока его действия, комитент должен уведомить комиссионера о прекращении договора не позднее чем за тридцать дней, если более продолжительный срок уведомления не предусмотрен договором.\n\nВ этом случае комитент обязан выплатить комиссионеру вознаграждение за сделки, совершенные им до прекращения договора, а также возместить комиссионеру понесенные им до прекращения договора расходы.\n\n3. В случае отмены поручения комитент обязан в срок, установленный договором комиссии, а если такой срок не установлен, незамедлительно распорядиться своим находящимся в ведении комиссионера имуществом. Если комитент не выполнит эту обязанность, комиссионер вправе сдать имущество на хранение за счет комитента либо продать его по возможно более выгодной для комитента цене.","article_title":"Статья 1003. Отмена комиссионного поручения комитентом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cb94a0fe86ff255784e38d7fd4c3fadc548b3af1396d2bf3e0c5f35f77ee42db"},{"code_id":"GK_RF_2","article_number":"1004","version_date":"1994-11-30","article_text":"1. Комиссионер не вправе, если иное не предусмотрено договором комиссии, отказаться от его исполнения, за исключением случая, когда договор заключен без указания срока его д\n\nействия. В этом случае комиссионер должен уведомить комитента о прекращении договора не позднее чем за тридцать дней, если более продолжительный срок уведомления не предусмотрен договором.\n\nКомиссионер обязан принять меры, необходимые для обеспечения сохранности имущества комитента.\n\n2. Комитент должен распорядиться своим находящимся в ведении комиссионера имуществом в течение пятнадцати дней со дня получения уведомления об отказе комиссионера исполнить поручение, если договором комиссии не установлен иной срок. Если он не выполнит эту обязанность, комиссионер вправе сдать имущество на хранение за счет комитента либо продать его по возможно более выгодной для комитента цене.\n\n3. Если договором комиссии не предусмотрено иное, комиссионер, отказавшийся от исполнения поручения, сохраняет право на комиссионное вознаграждение за сделки, совершенные им до прекращения договора, а также на возмещение понесенных до этого момента расходов.","article_title":"Статья 1004. Отказ комиссионера от исполнения договора комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b81fbb930d57c6ba1b883711682607c99d302b78d31098c7c8df352b12622922"},{"code_id":"GK_RF_2","article_number":"1005","version_date":"1994-11-30","article_text":"1. По агентскому договору одна сторона (агент) обязуется за вознаграждение совершать по поручению другой стороны (принципала) юридические и иные действия от своего имени, но за счет принципала либо от имени и за счет принципала.\n\nПо сделке, совершенной агентом с третьим лицом от своего имени и за счет принципала, приобретает права и становится обязанным агент, хотя бы принципал и был назван в сделке или вступил с третьим лицом в непосредственные отношения по исполнению сделки.\n\nПо сделке, совершенной агентом с третьим лицом от имени и за счет принципала, права и обязанности возникают непосредственно у принципала.\n\n2. В случаях, когда в агентском договоре, заключенном в письменной форме, предусмотрены общие полномочия агента на совершение сделок от имени принципала, последний в отношениях с третьими лицами не вправе ссылаться на отсутствие у агента надлежащих полномочий, если не докажет, что третье лицо знало или должно было знать об ограничении полномочий агента.\n\n3. Агентский договор может быть заключен на определенный срок или без указания срока его действия.\n\n4. Законом могут быть предусмотрены особенности отдельных видов агентского договора.","article_title":"Статья 1005. Агентский договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28fb17809e2f1d8ba4481a0c8bfc3114636d9b6e13f58de63f882cced95f4c57"},{"code_id":"GK_RF_2","article_number":"1006","version_date":"1994-11-30","article_text":"Принципал обязан уплатить агенту вознаграждение в размере и в порядке, установленных в агентском договоре.\n\nЕсли в агентском договоре размер агентского вознаграждения не предусмотрен и он не может быть определен исходя из условий договора, вознаграждение подлежит уплате в размере, определяемом в соответствии с пунктом 3 статьи 424 настоящего Кодекса.\n\nПри отсутствии в договоре условий о порядке уплаты агентского вознаграждения принципал обязан уплачивать вознаграждение в течение недели с момента представления ему агентом отчета за прошедший период, если из существа договора или обычаев делового оборота не вытекает иной порядок уплаты вознаграждения.","article_title":"Статья 1006. Агентское вознаграждение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ea13fde45a950f96529db126b28ee07dfe6fb10a7493978ccdff3728623ec55d"},{"code_id":"GK_RF_2","article_number":"1007","version_date":"1994-11-30","article_text":"1. Агентским договором может быть предусмотрено обязательство принципала не заключать аналогичных агентских договоров с другими агентами, действующими на определенной в договоре территории, либо воздерживаться от осуществления на этой территории самостоятельной деятельности, аналогичной деятельности, составляющей предмет агентского договора.\n\n2. Агентским договором может быть предусмотрено обязательство агента не заключать с другими принципалами аналогичных агентских договоров, которые должны исполняться на территории, полностью или частично совпадающей с территорией, указанной в договоре.\n\n3. Условия агентского договора, в силу которых агент вправе продавать товары, выполнять работы или оказывать услуги исключительно определенной категории покупателей (заказчиков) либо исключительно покупателям (заказчикам), имеющим место нахождения или место жительства на определенной в договоре территории, являются ничтожными.","article_title":"Статья 1007. Ограничения агентским договором прав принципала и агента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7b7c004b0670d619eff1c27666db27372086b8c1ce9a6c50c72f36c305c84c8c"},{"code_id":"GK_RF_2","article_number":"1008","version_date":"1994-11-30","article_text":"1. В ходе исполнения агентского договора агент обязан представлять принципалу отчеты в порядке и в сроки, которые предусмотрены договором. При отсутствии в договоре соответствующих условий отчеты представляются агентом по мере исполнения им договора либо по окончании действия договора.\n\n2. Если агентским договором не предусмотрено иное, к отчету агента должны быть приложены необходимые доказательства расходов, произведенных агентом за счет принципала.\n\n3. Принципал, имеющий возражения по отчету агента, должен сообщить о них агенту в течение тридцати дней со дня получения отчета, если соглашением сторон не установлен иной срок. В противном случае отчет считается принятым принципалом.","article_title":"Статья 1008. Отчеты агента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e565959f40347450e61e1ab228025473c7e03b7145012be40fdfe39e1facf005"},{"code_id":"GK_RF_2","article_number":"1009","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено агентским договором, агент вправе в целях исполнения договора заключить субагентский договор с другим лицом, оставаясь ответственным за действия субагента перед принципалом. В агентском договоре может быть предусмотрена обязанность агента заключить субагентский договор с указанием или без указания конкретных условий такого договора.\n\n2. Субагент не вправе заключать с третьими лицами сделки от имени лица, являющегося принципалом по агентскому договору, за исключением случаев, когда в соответствии с пунктом 1 статьи 187 настоящего Кодекса субагент может действовать на основе передоверия. Порядок и последствия такого передоверия определяются по правилам, предусмотренным статьей 976 настоящего Кодекса.","article_title":"Статья 1009. Субагентский договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4fcbc101ecb17c1924a8ae6b80fc607c2f19cfe12fd97adb0690e58e2a74abe0"},{"code_id":"GK_RF_2","article_number":"1010","version_date":"1994-11-30","article_text":"Агентский договор прекращается вследствие:\n\nотказа одной из сторон от исполнения договора, заключенного без определения срока окончания его действия;\n\nсмерти агента, признания его недееспособным, ограниченно дееспособным или безвестно отсутствующим;\n\nпризнания индивидуального предпринимателя, являющегося агентом, несостоятельным (банкротом).","article_title":"Статья 1010. Прекращение агентского договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1230010bbbb8ef56cc5679a3f0ae5db74f1277afd3a1b2f76f97b93035c1af57"},{"code_id":"GK_RF_2","article_number":"1011","version_date":"1994-11-30","article_text":"К отношениям, вытекающим из агентского договора, соответственно применяются правила, предусмотренные главой 49 или главой 51 настоящего Кодекса, в зависимости от того, действует агент по условиям этого договора от имени принципала или от своего имени, если эти правила не противоречат положениям настоящей главы или существу агентского договора.","article_title":"Статья 1011. Применение к агентским отношениям правил о договорах поручения и комиссии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c60fe6d2e89f53a3b43a941442b0928c27df6b9cc18dbebb1cea5a5589ebd45d"},{"code_id":"GK_RF_2","article_number":"1012","version_date":"1994-11-30","article_text":"1. По договору доверительного управления имуществом одна сторона (учредитель управления) передает другой стороне (доверительному управляющему) на определенный срок имущество в доверительное управление, а другая сторона обязуется осуществлять управление этим имуществом в интересах учредителя управления или указанного им лица (выгодоприобретателя).\n\nПередача имущества в доверительное управление не влечет перехода права собственности на него к доверительному управляющему.\n\n2. Осуществляя доверительное управление имуществом, доверительный управляющий вправе совершать в отношении этого имущества в соответствии с договором доверительного управления любые юридические и фактические действия в интересах выгодоприобретателя.\n\nЗаконом или договором могут быть предусмотрены ограничения в отношении отдельных действий по доверительному управлению имуществом.\n\n3. Сделки с переданным в доверительное управление имуществом доверительный управляющий совершает от своего имени, указывая при этом, что он действует в качестве такого управляющего. Это условие считается соблюденным, если при совершении действий, не требующих письменного оформления, другая сторона информирована об их совершении доверительным управляющим в этом качестве, а в письменных документах после имени или наименования доверительного управляющего сделана пометка \"Д.У.\".\n\nПри отсутствии указания о действии доверительного управляющего в этом качестве доверительный управляющий обязывается перед третьими лицами лично и отвечает перед ними только принадлежащим ему имуществом.","article_title":"Статья 1012. Договор доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3e67134a24214b7ab0fb882e7d525ad79bd6f1d1aaf2726c5086d97243d57aa"},{"code_id":"GK_RF_2","article_number":"1013","version_date":"1994-11-30","article_text":"1. Объектами доверительного управления могут быть предприятия и другие имущественные комплексы, отдельные объекты, относящиеся к недвижимому имуществу, ценные бумаги, права, удостоверенные бездокументарными ценными бумагами, исключительные права и другое имущество.\n\n2. Не могут быть самостоятельным объектом доверительного управления деньги, за исключением случаев, предусмотренных законом.\n\n3. Имущество, находящееся в хозяйственном ведении или оперативном управлении, не может быть передано в доверительное управление. Передача в доверительное управление имущества, находившегося в хозяйственном ведении или оперативном управлении, возможна только после ликвидации юридического лица, в хозяйственном ведении или оперативном управлении которого имущество находилось, либо прекращения права хозяйственного ведения или оперативного управления имуществом и поступления его во владение собственника по иным предусмотренным законом основаниям.","article_title":"Статья 1013. Объект доверительного управления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"55b53fd122ae38b687547abda017bb5d11f53a37c088fc6e9882fb1dddd89480"},{"code_id":"GK_RF_2","article_number":"1014","version_date":"1994-11-30","article_text":"Учредителем доверительного управления является собственник имущества, а в случаях, предусмотренных статьей 1026 настоящего Кодекса, другое лицо.","article_title":"Статья 1014. Учредитель управления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd74a7ef11f279d4747cdae6bfb8b607e6bc50421901de5066b2c3b9b7c86dc4"},{"code_id":"GK_RF_2","article_number":"1015","version_date":"1994-11-30","article_text":"1. Доверительным управляющим может быть индивидуальный предприниматель или коммерческая организация, за исключением унитарного предприятия.\n\nВ случаях, когда доверительное управление имуществом осуществляется по основаниям, предусмотренным законом, доверительным управляющим может быть гражданин, не являющийся предпринимателем, или некоммерческая организация, за исключением учреждения.\n\n2. Имущество не подлежит передаче в доверительное управление государственному органу или органу местного самоуправления.\n\n3. Доверительный управляющий не может быть выгодоприобретателем по договору доверительного управления имуществом.","article_title":"Статья 1015. Доверительный управляющий","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a0cb998595d33955d2d14e8b6618d01d1614290f6d4bd89450e4cad78c08e0d"},{"code_id":"GK_RF_2","article_number":"1016","version_date":"1994-11-30","article_text":"1. В договоре доверительного управления имуществом должны быть указаны:\n\nсостав имущества, передаваемого в доверительное управление;\n\nнаименование юридического лица или имя гражданина, в интересах которых осуществляется управление имуществом (учредителя управления или выгодоприобретателя);\n\nразмер и форма вознаграждения управляющему, если выплата вознаграждения предусмотрена договором;\n\nсрок действия договора.\n\n2. Договор доверительного управления имуществом заключается на срок, не превышающий пяти лет. Для отдельных видов имущества, передаваемого в доверительное управление, законом могут быть установлены иные предельные сроки, на которые может быть заключен договор.\n\nПри отсутствии заявления одной из сторон о прекращении договора по окончании срока его действия он считается продленным на тот же срок и на тех же условиях, какие были предусмотрены договором.","article_title":"Статья 1016. Существенные условия договора доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f302f51be7636ec741984020db18b9bfd9d73e79b54a7fa1e4328389a03cc6b3"},{"code_id":"GK_RF_2","article_number":"1017","version_date":"1994-11-30","article_text":"1. Договор доверительного управления имуществом должен быть заключен в письменной форме.\n\n2. Договор доверительного управления недвижимым имуществом должен быть заключен в форме, предусмотренной для договора продажи недвижимого имущества. Передача недвижимого имущества в доверительное управление подлежит государственной регистрации в том же порядке, что и переход права собственности на это имущество.\n\n3. Несоблюдение формы договора доверительного управления имуществом или требования о регистрации передачи недвижимого имущества в доверительное управление влечет недействительность договора.","article_title":"Статья 1017. Форма договора доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f634f06ef64663dc93da605fcdc36f94d6923526d3adb4ee07e69bbf7d15cc60"},{"code_id":"GK_RF_2","article_number":"1018","version_date":"1994-11-30","article_text":"1. Имущество, переданное в доверительное управление, обособляется от другого имущества учредителя управления, а также от имущества доверительного управляющего. Это имущество отражается у доверительного управляющего на отдельном балансе, и по нему ведется самостоятельный учет. Для расчетов по деятельности, связанной с доверительным управлением, открывается отдельный банковский счет.\n\n2. Обращение взыскания по долгам учредителя управления на имущество, переданное им в доверительное управление, не допускается, за исключением несостоятельности (банкротства) этого лица. При банкротстве учредителя управления доверительное управление этим имуществом прекращается и оно включается в конкурсную массу.","article_title":"Статья 1018. Обособление имущества, находящегося в доверительном управлении","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"884fbeb4c8a9c7711fe1028fa398c918907ed10872f6f0c1982bb205d2c1038b"},{"code_id":"GK_RF_2","article_number":"1019","version_date":"1994-11-30","article_text":"1. Передача заложенного имущества в доверительное управление не лишает залогодержателя права обратить взыскание на это имущество.\n\n2. Доверительный управляющий должен быть предупрежден о том, что передаваемое ему в доверительное управление имущество обременено залогом. Если доверительный управляющий не знал и не должен был знать об обременении залогом имущества, переданного ему в доверительное управление, он вправе потребовать в суде расторжения договора доверительного управления имуществом и уплаты причитающегося ему по договору вознаграждения за один год.","article_title":"Статья 1019. Передача в доверительное управление имущества, обремененного залогом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"08ff42795c38587d3b58bd6f1a7a1751a2665930b351fec29964c1f80f489b23"},{"code_id":"GK_RF_2","article_number":"1020","version_date":"1994-11-30","article_text":"1. Доверительный управляющий осуществляет в пределах, предусмотренных законом и договором доверительного управления имуществом, правомочия собственника в отношении имущества, переданного в доверительное управление. Распоряжение недвижимым имуществом доверительный управляющий осуществляет в случаях, предусмотренных договором доверительного управления.\n\n2. Права, приобретенные доверительным управляющим в результате действий по доверительному управлению имуществом, включаются в состав переданного в доверительное управление имущества. Обязанности, возникшие в результате таких действий доверительного управляющего, исполняются за счет этого имущества.\n\n3. Для защиты прав на имущество, находящееся в доверительном управлении, доверительный управляющий вправе требовать всякого устранения нарушения его прав (статьи 301, 302, 304, 305).\n\n4. Доверительный управляющий представляет учредителю управления и выгодоприобретателю отчет о своей деятельности в сроки и в порядке, которые установлены договором доверительного управления имуществом.","article_title":"Статья 1020. Права и обязанности доверительного управляющего","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47c5d2c09fd245608c6b46ea6dd11cda68f19cc901307ad71b588deb0925f8d3"},{"code_id":"GK_RF_2","article_number":"1021","version_date":"1994-11-30","article_text":"1. Доверительный управляющий осуществляет доверительное управление имуществом лично, кроме случаев, предусмотренных пунктом 2 настоящей статьи.\n\n2. Доверительный управляющий может поручить другому лицу совершать от имени доверительного управляющего действия, необходимые для управления имуществом, если он уполномочен на это договором доверительного управления имуществом, либо получил на это согласие учредителя в письменной форме, либо вынужден к этому в силу обстоятельств для обеспечения интересов учредителя управления или выгодоприобретателя и не имеет при этом возможности получить указания учредителя управления в разумный срок.\n\nДоверительный управляющий отвечает за действия избранного им поверенного как за свои собственные.","article_title":"Статья 1021. Передача доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"30bb4a05aba7f6e9e34129a610f0af8135ea48a5771e17e3017b528c4a2ea8c1"},{"code_id":"GK_RF_2","article_number":"1022","version_date":"1994-11-30","article_text":"1. Доверительный управляющий, не проявивший при доверительном управлении имуществом должной заботливости об интересах выгодоприобретателя или учредителя управления, возмещает выгодоприобретателю упущенную выгоду за время доверительного управления имуществом, а учредителю управления убытки, причиненные утратой или повреждением имущества, с учетом его естественного износа, а также упущенную выгоду.\n\nДоверительный управляющий несет ответственность за причиненные убытки, если не докажет, что эти убытки произошли вследствие непреодолимой силы либо действий выгодоприобретателя или учредителя управления.\n\n2. Обязательства по сделке, совершенной доверительным управляющим с превышением предоставленных ему полномочий или с нарушением установленных для него ограничений, несет доверительный управляющий лично. Если участвующие в сделке третьи лица не знали и не должны были знать о превышении полномочий или об установленных ограничениях, возникшие обязательства подлежат исполнению в порядке, установленном пунктом 3 настоящей статьи. Учредитель управления может в этом случае потребовать от доверительного управляющего возмещения понесенных им убытков.\n\n3. Долги по обязательствам, возникшим в связи с доверительным управлением имуществом, погашаются за счет этого имущества. В случае недостаточности этого имущества взыскание может быть обращено на имущество доверительного управляющего, а при недостаточности и его имущества на имущество учредителя управления, не переданное в доверительное управление.\n\n4. Договор доверительного управления имуществом может предусматривать предоставление доверительным управляющим залога в обеспечение возмещения убытков, которые могут быть причинены учредителю управления или выгодоприобретателю ненадлежащим исполнением договора доверительного управления.","article_title":"Статья 1022. Ответственность доверительного управляющего","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a01b9b94aaf1d335421225084e8dac01878cdcce27e8ad17277a1ad7a6ec5682"},{"code_id":"GK_RF_2","article_number":"1023","version_date":"1994-11-30","article_text":"Доверительный управляющий имеет право на вознаграждение, предусмотренное договором доверительного управления имуществом, а также на возмещение необходимых расходов, произведенных им при доверительном управлении имуществом, за счет доходов от использования этого имущества.","article_title":"Статья 1023. Вознаграждение доверительному управляющему","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"295dfe5b68984b8584be46d884dac85d1f6384d13d5931382f85aa8a4f0f1b8d"},{"code_id":"GK_RF_2","article_number":"1024","version_date":"1994-11-30","article_text":"1. Договор доверительного управления имуществом прекращается вследствие:\n\nсмерти гражданина, являющегося выгодоприобретателем, или ликвидации юридического лица - выгодоприобретателя, если договором не предусмотрено иное;\n\nотказа выгодоприобретателя от получения выгод по договору, если договором не предусмотрено иное;\n\nсмерти гражданина, являющегося доверительным управляющим, признания его недееспособным, ограниченно дееспособным или безвестно отсутствующим, а также признания индивидуального предпринимателя несостоятельным (банкротом);\n\nотказа доверительного управляющего или учредителя управления от осуществления доверительного управления в связи с невозможностью для доверительного управляющего лично осуществлять доверительное управление имуществом;\n\nотказа учредителя управления от договора по иным причинам, чем та, которая указана в абзаце пятом настоящего пункта, при условии выплаты доверительному управляющему обусловленного договором вознаграждения;\n\nпризнания несостоятельным (банкротом) гражданина-предпринимателя, являющегося учредителем управления.\n\n2. При отказе одной стороны от договора доверительного управления имуществом другая сторона должна быть уведомлена об этом за три месяца до прекращения договора, если договором не предусмотрен иной срок уведомления.\n\n3. При прекращении договора доверительного управления имущество, находящееся в доверительном управлении, передается учредителю управления, если договором не предусмотрено иное.","article_title":"Статья 1024. Прекращение договора доверительного управления имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8756194a802d6a7cea94a18d96fb190720b1eebbaca53d6d8ed54117b8617bc7"},{"code_id":"GK_RF_2","article_number":"1025","version_date":"1994-11-30","article_text":"При передаче в доверительное управление ценных бумаг может быть предусмотрено объединение ценных бумаг, передаваемых в доверительное управление разными лицами.\n\nПравомочия доверительного управляющего по распоряжению ценными бумагами определяются в договоре доверительного управления.\n\nОсобенности доверительного управления ценными бумагами определяются законом.\n\nа настоящей статьи соответственно применяются к правам, удостоверенным бездокументарными ценными бумагами (статья 149).","article_title":"Статья 1025. Передача в доверительное управление ценных бумаг","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"14bf5b17df5a574ab57c8ccf701ed2710e9508fea742e0d8e9312b0575f1ade0"},{"code_id":"GK_RF_2","article_number":"1026","version_date":"1994-11-30","article_text":"1. Доверительное управление имуществом может быть также учреждено:\n\nвследствие необходимости постоянного управления имуществом подопечного в случаях, предусмотренных статьей 38 настоящего Кодекса;\n\nвследствие необходимости управления наследственным имуществом (статья 1173);  (В редакции Федерального закона от 29.07.2017 № 259-ФЗ)\n\nпо иным основаниям, предусмотренным законом.\n\n2. Правила, предусмотренные настоящей главой, соответственно применяются к отношениям по доверительному управлению имуществом, учрежденному по основаниям, указанным в пункте 1 настоящей статьи, если иное не предусмотрено законом и не вытекает из существа таких отношений.\n\nВ случаях, когда доверительное управление имуществом учреждается по основаниям, указанным в пункте 1 настоящей статьи, права учредителя управления, предусмотренные правилами настоящей главы, принадлежат соответственно органу опеки и попечительства, нотариусу или иному лицу, указанному в законе. (В редакции Федерального закона от 29.07.2017 № 259-ФЗ)","article_title":"Статья 1026. Доверительное управление имуществом по основаниям, предусмотренным законом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c857dda82344fe9aceb25a4fc7100bb13758544266d519d3d22c930a57825d0e"},{"code_id":"GK_RF_2","article_number":"1028","version_date":"1994-11-30","article_text":"1. Договор коммерческой концессии должен быть заключен в письменной форме.\n\nНесоблюдение письменной формы договора влечет его недействительность. Такой договор считается ничтожным.","article_title":"Статья 1028. Форма и регистрация договора коммерческой концессии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02bf234124ca3ff29161b8026ba0cf13ad41ed2efb025b0ffde9253b888b5b3e"},{"code_id":"GK_RF_2","article_number":"1029","version_date":"1994-11-30","article_text":"1. Договором коммерческой концессии может быть предусмотрено право пользователя разрешать другим лицам использование предоставленного ему комплекса исключительных прав или части этого комплекса на условиях субконцессии, согласованных им с правообладателем либо определенных в договоре коммерческой концессии. В договоре может быть предусмотрена обязанность пользователя предоставить в течение определенного срока определенному числу лиц право пользования указанными правами на условиях субконцессии.\n\nДоговор коммерческой субконцессии не может быть заключен на более длительный срок, чем договор коммерческой концессии, на основании которого он заключается.\n\n2. Если договор коммерческой концессии является недействительным, недействительны и заключенные на основании его договоры коммерческой субконцессии.\n\n3. Если иное не предусмотрено договором коммерческой концессии, заключенным на срок, при его досрочном прекращении права и обязанности вторичного правообладателя по договору коммерческой субконцессии (пользователя по договору коммерческой концессии) переходят к правообладателю, если он не откажется от принятия на себя прав и обязанностей по этому договору. Это правило соответственно применяется при расторжении договора коммерческой концессии, заключенного без указания срока.\n\n4. Пользователь несет субсидиарную ответственность за вред, причиненный правообладателю действиями вторичных пользователей, если иное не предусмотрено договором коммерческой концессии.\n\n5. К договору коммерческой субконцессии применяются предусмотренные настоящей главой правила о договоре коммерческой концессии, если иное не вытекает из особенностей субконцессии.","article_title":"Статья 1029. Коммерческая субконцессия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77e6ea56f4311cc3c0421db921599385aa6ce1a65cee4a035cc8865b8161788a"},{"code_id":"GK_RF_2","article_number":"1030","version_date":"1994-11-30","article_text":"Вознаграждение по договору коммерческой концессии может выплачиваться пользователем правообладателю в форме фиксированных разовых и (или) периодических платежей, отчислений от выручки, наценки на оптовую цену товаров, передаваемых правообладателем для перепродажи, или в иной форме, предусмотренной договором. (В редакции Федерального закона от 18.07.2011 № 216-ФЗ)","article_title":"Статья 1030. Вознаграждение по договору коммерческой концессии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57e184c75081ad8052331348b9ad8d335f669b2c17c969a72979e41ad9115a36"},{"code_id":"GK_RF_2","article_number":"1031","version_date":"1994-11-30","article_text":"обеспечить государственную регистрацию предоставления права использования в предпринимательской деятельности пользователя комплекса принадлежащих правообладателю исключительных прав по договору коммерческой концессии (пункт 2 статьи 1028); (В редакции федеральных законов от 18.12.2006 № 231-ФЗ; от 12.03.2014 № 35-ФЗ)\n\nоказывать пользователю постоянное техническое и консультативное содействие, включая содействие в обучении и повышении квалификации работников;\n\nконтролировать качество товаров (работ, услуг), производимых (выполняемых, оказываемых) пользователем на основании договора коммерческой концессии.","article_title":"Статья 1031. Обязанности правообладателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28ae344d6dfa932c8a97b59bd64ea7476b3427dee78400abfbb1cca9a1922778"},{"code_id":"GK_RF_2","article_number":"1032","version_date":"1994-11-30","article_text":"С учетом характера и особенностей деятельности, осуществляемой пользователем по договору коммерческой концессии, пользователь обязан:\n\nиспользовать при осуществлении предусмотренной договором деятельности коммерческое обозначение, товарный знак, знак обслуживания или иное средство индивидуализации правообладателя указанным в договоре образом; (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)\n\nобеспечивать соответствие качества производимых им на основе договора товаров, выполняемых работ, оказываемых услуг качеству аналогичных товаров, работ или услуг, производимых, выполняемых или оказываемых непосредственно правообладателем;\n\nсоблюдать инструкции и указания правообладателя, направленные на обеспечение соответствия характера, способов и условий использования комплекса исключительных прав тому, как он используется правообладателем, в том числе указания, касающиеся внешнего и внутреннего оформления коммерческих помещений, используемых пользователем при осуществлении предоставленных ему по договору прав;\n\nоказывать покупателям (заказчикам) все дополнительные услуги, на которые они могли бы рассчитывать, приобретая (заказывая) товар (работу, услугу) непосредственно у правообладателя;\n\nне разглашать секреты производства (ноу-хау) правообладателя и другую полученную от него конфиденциальную коммерческую информацию; (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)\n\nпредоставить оговоренное количество субконцессий, если такая обязанность предусмотрена договором;\n\nинформировать покупателей (заказчиков) наиболее очевидным для них способом о том, что он использует коммерческое обозначение, товарный знак, знак обслуживания или иное средство индивидуализации в силу договора коммерческой концессии. (В редакции Федерального закона от 18.12.2006 № 231-ФЗ)","article_title":"Статья 1032. Обязанности пользователя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"19a51026b60ed1761443e82a65cd9b30658a70b34df591ed332c46a51c045f99"},{"code_id":"GK_RF_2","article_number":"1033","version_date":"1994-11-30","article_text":"1. Договором коммерческой концессии могут быть предусмотрены ограничения прав сторон по этому договору, в частности могут быть предусмотрены:\n\nобязательство правообладателя не предоставлять другим лицам аналогичные комплексы исключительных прав для их использования на закрепленной за пользователем территории либо воздерживаться от собственной аналогичной деятельности на этой территории;\n\nобязательство пользователя не конкурировать с правообладателем на территории, на которую распространяется действие договора коммерческой концессии в отношении предпринимательской деятельности, осуществляемой пользователем с использованием принадлежащих правообладателю исключительных прав;\n\nотказ пользователя от получения по договорам коммерческой концессии аналогичных прав у конкурентов (потенциальных конкурентов) правообладателя;\n\nобязательство пользователя реализовывать, в том числе перепродавать, произведенные и (или) закупленные товары, выполнять работы или оказывать услуги с использованием принадлежащих правообладателю исключительных прав по установленным правообладателем ценам, а равно обязательство пользователя не осуществлять реализацию аналогичных товаров, выполнение аналогичных работ или оказание аналогичных услуг с использованием товарных знаков или коммерческих обозначений других правообладателей;\n\nобязательство пользователя продавать товары, выполнять работы или оказывать услуги исключительно в пределах определенной территории;\n\nобязательство пользователя согласовывать с правообладателем место расположения коммерческих помещений, используемых при осуществлении предоставленных по договору исключительных прав, а также их внешнее и внутреннее оформление.\n\n2. Условия договора коммерческой концессии, предусматривающие обязательство пользователя продавать товары, выполнять работы или оказывать услуги исключительно покупателям (заказчикам), имеющим место нахождения, место жительства на определенной договором территории, являются ничтожными.\n\n3. Ограничительные условия могут быть признаны недействительными по требованию антимонопольного органа или иного заинтересованного лица, если эти условия с учетом состояния соответствующего рынка и экономического положения сторон противоречат антимонопольному законодательству.\n\n(Статья в редакции Федерального закона от 18.07.2011 № 216-ФЗ)","article_title":"Статья 1033. Ограничения прав сторон по договору коммерческой концессии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02595411da1de8cb4568f489d7cfb8425041d53a2b54dd29e2a2b48dfdb314c9"},{"code_id":"GK_RF_2","article_number":"1034","version_date":"1994-11-30","article_text":"Правообладатель несет субсидиарную ответственность по предъявляемым к пользователю требованиям о несоответствии качества товаров (работ, услуг), продаваемых (выполняемых, оказываемых) пользователем по договору коммерческой концессии.\n\nПо требованиям, предъявляемым к пользователю как изготовителю продукции (товаров) правообладателя, правообладатель отвечает солидарно с пользователем.","article_title":"Статья 1034. Ответственность правообладателя по требованиям, предъявляемым к пользователю","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c435f0927a4904445584c5bdf8016dbc6bc214e977dcaec7cc7b3fcfbc027141"}]$law7v011$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
